/** Pure, unit-tested mappings used by the live scientific views. */
export function rms(samples: ArrayLike<number>): number {
  if (!samples.length) return 0;
  let sum = 0;
  for (let i = 0; i < samples.length; i++) sum += samples[i] * samples[i];
  return Math.sqrt(sum / samples.length);
}

export function digitalLevel(value: number): number {
  return value > 0 && Number.isFinite(value)
    ? 20 * Math.log10(value)
    : -Infinity;
}

export function binFrequency(
  index: number,
  sampleRate: number,
  fftSize: number,
): number {
  return (index * sampleRate) / fftSize;
}

export function strongestBin(
  spectrum: ArrayLike<number>,
  sampleRate: number,
  fftSize: number,
): { frequency: number; level: number; bin: number } | null {
  let index = -1;
  let peak = -Infinity;
  // Ignore DC, which is not an oscillation or a musical frequency.
  for (let i = 1; i < spectrum.length; i++) {
    if (Number.isFinite(spectrum[i]) && spectrum[i] > peak) {
      index = i;
      peak = spectrum[i];
    }
  }
  return index < 0 || peak < -140
    ? null
    : {
        frequency: binFrequency(index, sampleRate, fftSize),
        level: peak,
        bin: index,
      };
}

/** Last rising zero crossing with enough following samples for the full window.
 * Aperiodic, silent, or too-short captures fall back to the latest full window.
 * The trigger changes the origin, never the horizontal or vertical scale.
 */
export function triggerStart(
  samples: ArrayLike<number>,
  sampleCount: number,
): { index: number; triggered: boolean } {
  const last = Math.max(0, samples.length - Math.max(2, sampleCount));
  for (let i = last; i >= 1; i--) {
    if (samples[i - 1] <= 0 && samples[i] > 0)
      return { index: i, triggered: true };
  }
  return { index: last, triggered: false };
}

export const SOUND_SPEED = 343;
export const AIR_SPAN_METRES = 2;
export const SLOW_MOTION_DIVISOR = 220;

export function airParameters(frequency: number, amplitude: number) {
  const f = Math.max(1, frequency);
  const k = (2 * Math.PI * f) / SOUND_SPEED;
  // kA <= .42 guarantees d(x + ξ)/dx >= .58: markers cannot cross.
  // This is deliberately illustrative, not a gain-to-metres calibration.
  const displacementAmplitude =
    (0.42 * Math.min(1, Math.max(0, amplitude))) / k;
  return { k, displacementAmplitude, wavelength: SOUND_SPEED / f };
}

export function particleDisplacement(
  x: number,
  phase: number,
  frequency: number,
  amplitude: number,
): number {
  const { k, displacementAmplitude } = airParameters(frequency, amplitude);
  return displacementAmplitude * Math.cos(k * x - phase);
}

export function compressionAt(
  x: number,
  phase: number,
  frequency: number,
  amplitude: number,
): number {
  const { k, displacementAmplitude } = airParameters(frequency, amplitude);
  // Pressure perturbation is proportional to minus the displacement gradient.
  return k * displacementAmplitude * Math.sin(k * x - phase);
}
