import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
} from "react";
import { Icon } from "./Icon";
type Props = {
  label: string;
  value: number;
  min: number;
  max: number;
  step?: number;
  unit: string;
  color: "teal" | "coral";
  locked: boolean;
  onLock: () => void;
  onChange: (value: number) => void;
  onReset: () => void;
};
export function Knob({
  label,
  value,
  min,
  max,
  step = 1,
  unit,
  color,
  locked,
  onLock,
  onChange,
  onReset,
}: Props) {
  const drag = useRef<{ x: number; y: number; value: number } | null>(null);
  const editing = useRef(false);
  const cancelled = useRef(false);
  const [draft, setDraft] = useState(String(value));
  useEffect(() => {
    if (!editing.current) setDraft(String(value));
  }, [value]);
  const clamp = (n: number) =>
    Math.max(min, Math.min(max, Math.round(n / step) * step));
  const change = (n: number) => {
    if (!locked) onChange(clamp(n));
  };
  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const d = (e.shiftKey ? 10 : 1) * step;
    if (
      [
        "ArrowUp",
        "ArrowRight",
        "ArrowDown",
        "ArrowLeft",
        "Home",
        "End",
        "PageUp",
        "PageDown",
      ].includes(e.key)
    )
      e.preventDefault();
    if (e.key === "ArrowUp" || e.key === "ArrowRight") change(value + d);
    if (e.key === "ArrowDown" || e.key === "ArrowLeft") change(value - d);
    if (e.key === "PageUp") change(value + 10 * step);
    if (e.key === "PageDown") change(value - 10 * step);
    if (e.key === "Home") change(min);
    if (e.key === "End") change(max);
  };
  const pointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (locked) return;
    e.currentTarget.focus();
    e.currentTarget.setPointerCapture(e.pointerId);
    drag.current = { x: e.clientX, y: e.clientY, value };
  };
  return (
    <div className={`control-module ${color} ${locked ? "is-locked" : ""}`}>
      <div className="control-heading">
        <span>{label}</span>
        <button
          className="icon-button lock-button"
          aria-label={`${locked ? "Unlock" : "Lock"} ${label.toLowerCase()}`}
          aria-pressed={locked}
          title={`${locked ? "Unlock" : "Lock"} this variable`}
          onClick={onLock}
        >
          <Icon name={locked ? "lock" : "unlock"} size={15} />
        </button>
      </div>
      <div className="dial-surround">
        <div className="dial-ticks" aria-hidden="true" />
        <div
          className="dial"
          role="slider"
          aria-label={`${label} knob`}
          aria-valuemin={min}
          aria-valuemax={max}
          aria-valuenow={value}
          aria-valuetext={`${value} ${unit}`}
          aria-disabled={locked}
          tabIndex={locked ? -1 : 0}
          onKeyDown={onKey}
          onPointerDown={pointerDown}
          onPointerMove={(e) => {
            if (drag.current) {
              const delta =
                e.clientX - drag.current.x + (drag.current.y - e.clientY);
              change(
                drag.current.value +
                  (delta * (max - min)) / (e.shiftKey ? 1800 : 240),
              );
            }
          }}
          onPointerUp={() => (drag.current = null)}
          onPointerCancel={() => (drag.current = null)}
          onLostPointerCapture={() => (drag.current = null)}
          style={
            {
              "--angle": `${-135 + ((value - min) / (max - min)) * 270}deg`,
            } as CSSProperties
          }
        >
          <span className="dial-face">
            <span className="dial-pointer" />
          </span>
        </div>
        <span className="dial-min">{min}</span>
        <span className="dial-max">{max}</span>
      </div>
      <div className="numeric-readout">
        <input
          aria-label={`${label} value`}
          title="Type a value, then press Enter or leave the field"
          type="number"
          min={min}
          max={max}
          step={step}
          disabled={locked}
          value={draft}
          onFocus={() => {
            editing.current = true;
            cancelled.current = false;
          }}
          onChange={(e) => setDraft(e.target.value)}
          onBlur={() => {
            editing.current = false;
            if (
              cancelled.current ||
              draft.trim() === "" ||
              !Number.isFinite(Number(draft))
            ) {
              setDraft(String(value));
              cancelled.current = false;
            } else {
              const next = clamp(Number(draft));
              change(next);
              setDraft(String(next));
            }
          }}
          onKeyDown={(e) => {
            if (e.key === "Enter") e.currentTarget.blur();
            if (e.key === "Escape") {
              cancelled.current = true;
              e.currentTarget.blur();
            }
          }}
        />
        <span>{unit}</span>
      </div>
      <input
        className="control-slider"
        aria-label={`${label} slider`}
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        disabled={locked}
        onChange={(e) => change(Number(e.target.value))}
      />
      <div className="control-foot">
        <span>
          {locked
            ? "Variable locked"
            : color === "teal"
              ? "Changes pitch"
              : "Changes signal height"}
        </span>
        <button
          className="text-button"
          aria-label={`Reset ${label.toLowerCase()}`}
          disabled={locked}
          onClick={onReset}
        >
          <Icon name="reset" size={13} />
        </button>
      </div>
    </div>
  );
}
