import { useEffect, useId, useRef, useState } from "react";
import {
  AIR_SPAN_METRES,
  SOUND_SPEED,
  SLOW_MOTION_DIVISOR,
  airParameters,
  compressionAt,
  particleDisplacement,
} from "./science";
import "./visuals.css";

export interface AirModelProps {
  frequency: number;
  amplitude: number;
  waveform?: string;
  frozen?: boolean;
}

export function AirModel({
  frequency,
  amplitude,
  waveform = "sine",
  frozen = false,
}: AirModelProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const phaseRef = useRef(0);
  const paintRef = useRef<(() => void) | null>(null);
  const [paused, setPaused] = useState(false);
  const [reducedMotion, setReducedMotion] = useState(false);
  const propsRef = useRef({
    frequency,
    amplitude,
    paused,
    frozen,
    reducedMotion,
  });
  propsRef.current = { frequency, amplitude, paused, frozen, reducedMotion };
  const descriptionId = useId();
  const parameters = airParameters(frequency, amplitude);

  useEffect(() => {
    const preference = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReducedMotion(preference.matches);
    update();
    preference.addEventListener("change", update);
    return () => preference.removeEventListener("change", update);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    const host = hostRef.current;
    if (!canvas || !host) return;
    const context = canvas.getContext("2d");
    if (!context) return;
    let raf = 0;
    let last = 0;
    let width = 600;
    let height = 290;
    let dpr = 1;
    let disposed = false;
    let lastStaticKey = "";

    function roundedRect(
      x: number,
      y: number,
      w: number,
      h: number,
      r: number,
    ) {
      if (!context) return;
      context.beginPath();
      context.roundRect(x, y, w, h, r);
    }

    function arrow(
      x1: number,
      y1: number,
      x2: number,
      y2: number,
      color: string,
      size = 5,
    ) {
      if (!context) return;
      context.strokeStyle = color;
      context.fillStyle = color;
      context.lineWidth = 1.6;
      context.beginPath();
      context.moveTo(x1, y1);
      context.lineTo(x2, y2);
      context.stroke();
      const angle = Math.atan2(y2 - y1, x2 - x1);
      context.beginPath();
      context.moveTo(x2, y2);
      context.lineTo(
        x2 - size * Math.cos(angle - 0.5),
        y2 - size * Math.sin(angle - 0.5),
      );
      context.lineTo(
        x2 - size * Math.cos(angle + 0.5),
        y2 - size * Math.sin(angle + 0.5),
      );
      context.closePath();
      context.fill();
    }

    function render() {
      if (!context) return;
      const props = propsRef.current;
      const w = width;
      const h = height;
      const narrow = w < 420;
      const presentation = !!host?.closest(".presentation") && w >= 480;
      const left = narrow ? 60 : 84;
      const right = w - 20;
      const span = right - left;
      const pxPerMetre = span / AIR_SPAN_METRES;
      const top = presentation ? 90 : 62;
      const bottom = h - (presentation ? 78 : 63);
      const centre = (top + bottom) / 2;
      const phase = phaseRef.current;
      const { k } = airParameters(props.frequency, props.amplitude);
      context.setTransform(dpr, 0, 0, dpr, 0, 0);
      context.clearRect(0, 0, w, h);
      const backdrop = context.createLinearGradient(0, 0, 0, h);
      backdrop.addColorStop(0, "#FBF9F3");
      backdrop.addColorStop(1, "#EBF0E5");
      context.fillStyle = backdrop;
      context.fillRect(0, 0, w, h);

      context.fillStyle = "#4B605B";
      context.font = `${presentation ? 16 : 11}px system-ui, sans-serif`;
      context.textAlign = "left";
      context.fillText(
        "Wave energy travels this way",
        left,
        presentation ? 27 : 24,
      );
      arrow(
        left,
        presentation ? 46 : 36,
        right - 6,
        presentation ? 46 : 36,
        "#287C83",
        6,
      );

      // Soft air bands are determined by −∂ξ/∂x at equilibrium coordinates.
      // Positive = compression; negative = rarefaction.
      context.save();
      roundedRect(left - 9, top - 17, span + 12, bottom - top + 36, 15);
      context.clip();
      for (let px = 0; px < span; px += 3) {
        const x = px / pxPerMetre;
        const pressure = compressionAt(
          x,
          phase,
          props.frequency,
          props.amplitude,
        );
        context.fillStyle =
          pressure > 0
            ? `rgba(40,124,131,${pressure * 0.27})`
            : `rgba(210,167,75,${-pressure * 0.18})`;
        context.fillRect(left + px, top - 17, 3.2, bottom - top + 36);
      }

      const rows = 5;
      const columns = 43;
      const highlightColumn = 17;
      const highlightRow = 2;
      const spacing = AIR_SPAN_METRES / (columns - 1);
      const highlightX0 = highlightColumn * spacing;
      const highlightEquilibriumPx = left + highlightX0 * pxPerMetre;
      const highlightX =
        highlightEquilibriumPx +
        particleDisplacement(
          highlightX0,
          phase,
          props.frequency,
          props.amplitude,
        ) *
          pxPerMetre;

      // Equilibrium track and ring make the local back-and-forth motion explicit.
      context.strokeStyle = "#B9876C";
      context.lineWidth = 1.2;
      context.setLineDash([3, 3]);
      context.beginPath();
      context.moveTo(highlightEquilibriumPx - 20, centre);
      context.lineTo(highlightEquilibriumPx + 20, centre);
      context.stroke();
      context.setLineDash([]);
      context.beginPath();
      context.arc(highlightEquilibriumPx, centre, 7.8, 0, Math.PI * 2);
      context.stroke();

      for (let row = 0; row < rows; row++) {
        const y = top + (row / (rows - 1)) * (bottom - top);
        for (let column = 0; column < columns; column++) {
          const equilibrium = column * spacing;
          const x =
            left +
            (equilibrium +
              particleDisplacement(
                equilibrium,
                phase,
                props.frequency,
                props.amplitude,
              )) *
              pxPerMetre;
          const selected = column === highlightColumn && row === highlightRow;
          const radius = selected ? 5.5 : narrow ? 2.25 : 2.9;
          context.fillStyle = selected
            ? "rgba(116,66,45,.15)"
            : "rgba(43,78,70,.10)";
          context.beginPath();
          context.ellipse(
            x + 1.5,
            y + 3.2,
            radius + 1.2,
            radius * 0.55,
            0,
            0,
            Math.PI * 2,
          );
          context.fill();
          const bead = context.createRadialGradient(
            x - radius * 0.38,
            y - radius * 0.4,
            0,
            x,
            y,
            radius,
          );
          if (selected) {
            bead.addColorStop(0, "#F2AB8E");
            bead.addColorStop(0.45, "#D87B5C");
            bead.addColorStop(1, "#A6533E");
          } else {
            bead.addColorStop(0, "#B5D0B9");
            bead.addColorStop(0.48, "#72A197");
            bead.addColorStop(1, "#3F756F");
          }
          context.fillStyle = bead;
          context.beginPath();
          context.arc(x, y, radius, 0, Math.PI * 2);
          context.fill();
        }
      }
      context.restore();

      // Tactile speaker in side section; diaphragm follows the x=0 displacement.
      const speakerLeft = narrow ? 9 : 19;
      const speakerWidth = narrow ? 34 : 43;
      const speakerTop = centre - 63;
      const casing = context.createLinearGradient(
        speakerLeft,
        0,
        speakerLeft + speakerWidth,
        0,
      );
      casing.addColorStop(0, "#386D70");
      casing.addColorStop(0.3, "#64928C");
      casing.addColorStop(1, "#365C60");
      context.fillStyle = "rgba(39,55,45,.13)";
      roundedRect(speakerLeft + 3, speakerTop + 6, speakerWidth + 3, 129, 11);
      context.fill();
      context.fillStyle = casing;
      roundedRect(speakerLeft, speakerTop, speakerWidth, 126, 10);
      context.fill();
      context.fillStyle = "#C9B48C";
      roundedRect(speakerLeft + 3, speakerTop + 4, 7, 118, 4);
      context.fill();
      const diaphragmX =
        left -
        12 +
        particleDisplacement(0, phase, props.frequency, props.amplitude) *
          pxPerMetre;
      context.fillStyle = "#283E42";
      context.beginPath();
      context.moveTo(speakerLeft + speakerWidth - 3, centre - 48);
      context.lineTo(diaphragmX, centre - 28);
      context.lineTo(diaphragmX, centre + 28);
      context.lineTo(speakerLeft + speakerWidth - 3, centre + 48);
      context.closePath();
      context.fill();
      const membrane = context.createLinearGradient(
        diaphragmX - 4,
        0,
        diaphragmX + 4,
        0,
      );
      membrane.addColorStop(0, "#9DA9A5");
      membrane.addColorStop(0.4, "#E7E4D7");
      membrane.addColorStop(1, "#758B86");
      context.fillStyle = membrane;
      roundedRect(diaphragmX - 2, centre - 34, 5, 68, 3);
      context.fill();

      // Labels point to density regions selected from this same displacement model.
      if (w >= 500 && props.amplitude > 0.02) {
        const candidates: { x: number; compression: boolean }[] = [];
        for (let n = -20; n < 20; n++) {
          const c = (Math.PI / 2 + phase + 2 * Math.PI * n) / k;
          const r = ((3 * Math.PI) / 2 + phase + 2 * Math.PI * n) / k;
          if (c > 0.24 && c < 1.78)
            candidates.push({ x: c, compression: true });
          if (r > 0.24 && r < 1.78)
            candidates.push({ x: r, compression: false });
        }
        const compress = candidates
          .filter((c) => c.compression)
          .sort((a, b) => Math.abs(a.x - 0.6) - Math.abs(b.x - 0.6))[0];
        const rare = candidates
          .filter((c) => !c.compression)
          .sort((a, b) => Math.abs(a.x - 1.5) - Math.abs(b.x - 1.5))[0];
        const labels = [compress, rare].filter(
          (v): v is { x: number; compression: boolean } => !!v,
        );
        for (const marker of labels) {
          const x = left + marker.x * pxPerMetre;
          // Keep labels away from the highlighted particle callout below.
          context.font = `${presentation ? 14 : 10}px system-ui, sans-serif`;
          context.textAlign = "center";
          context.fillStyle = marker.compression ? "#286E73" : "#8E681F";
          const label = marker.compression ? "COMPRESSION" : "RAREFACTION";
          context.fillText(label, x, top - 24);
          context.strokeStyle = marker.compression ? "#83AAA2" : "#C3AD7E";
          context.lineWidth = 1;
          context.beginPath();
          context.moveTo(x, top - 20);
          context.lineTo(x, top - 8);
          context.stroke();
        }
      }

      // Leader stays on the selected particle; the ring stays at equilibrium.
      context.strokeStyle = "#A65D45";
      context.lineWidth = 1;
      context.beginPath();
      context.moveTo(highlightX, centre + 9);
      context.lineTo(highlightX, bottom + 14);
      context.lineTo(highlightEquilibriumPx + 19, bottom + 25);
      context.stroke();
      context.textAlign = "left";
      context.font = `500 ${presentation ? 15 : 11}px system-ui, sans-serif`;
      context.fillStyle = "#934C37";
      context.fillText(
        "One particle, staying local",
        Math.max(left + 4, highlightEquilibriumPx - 42),
        bottom + 38,
      );

      context.fillStyle = "#5B6A60";
      context.font = `${presentation ? 14 : 10}px system-ui, sans-serif`;
      context.textAlign = "left";
      context.fillText("Speaker", speakerLeft, centre + 79);
      context.textAlign = "right";
      context.fillText("2 m model span", right, h - 7);
    }

    function resize() {
      if (!canvas || !host) return;
      const bounds = host.getBoundingClientRect();
      width = Math.max(220, bounds.width);
      height = Math.max(260, bounds.height);
      dpr = Math.min(3, window.devicePixelRatio || 1);
      canvas.width = Math.round(width * dpr);
      canvas.height = Math.round(height * dpr);
      render();
    }

    function loop(now: number) {
      if (disposed || document.hidden) return;
      const props = propsRef.current;
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 0;
      last = now;
      const moving = !props.paused && !props.frozen && !props.reducedMotion;
      if (moving)
        phaseRef.current =
          (phaseRef.current +
            (2 * Math.PI * props.frequency * dt) / SLOW_MOTION_DIVISOR) %
          (2 * Math.PI);
      const staticKey = `${props.frequency}:${props.amplitude}:${phaseRef.current}:${!!host?.closest(".presentation")}`;
      if (moving || staticKey !== lastStaticKey) render();
      lastStaticKey = staticKey;
      raf = requestAnimationFrame(loop);
    }

    function visibility() {
      cancelAnimationFrame(raf);
      last = 0;
      if (!document.hidden) raf = requestAnimationFrame(loop);
    }
    const observer = new ResizeObserver(resize);
    observer.observe(host);
    resize();
    document.addEventListener("visibilitychange", visibility);
    paintRef.current = render;
    if (!document.hidden) raf = requestAnimationFrame(loop);
    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
      paintRef.current = null;
    };
  }, []);

  const motionPaused = paused || frozen || reducedMotion;
  function step() {
    phaseRef.current = (phaseRef.current + Math.PI / 8) % (2 * Math.PI);
    setPaused(true);
    paintRef.current?.();
  }
  return (
    <figure className="air-model" aria-label="Longitudinal sound-wave model">
      <div className="air-model__heading">
        <span className="air-model__model-label">Illustrative model</span>
        <span>
          {frequency} Hz · λ ≈ {parameters.wavelength.toFixed(2)} m
        </span>
      </div>
      <div className="air-model__canvas" ref={hostRef}>
        <canvas
          ref={canvasRef}
          role="img"
          aria-describedby={descriptionId}
          aria-label="Air-particle markers move back and forth horizontally while compression travels to the right"
        >
          Air-particle markers oscillate horizontally around fixed equilibrium
          positions. Compressions propagate right. A highlighted particle
          remains near its equilibrium ring.
        </canvas>
      </div>
      <figcaption>
        <div className="air-model__legend">
          <span>
            <i
              className="air-model__legend-dot air-model__legend-dot--compression"
              aria-hidden="true"
            />
            Closer particles: compression
          </span>
          <span>
            <i
              className="air-model__legend-dot air-model__legend-dot--rarefaction"
              aria-hidden="true"
            />
            Wider gaps: rarefaction
          </span>
        </div>
        <div className="air-model__controls">
          <strong>Slow-motion model — not real-time particle motion</strong>
          <div>
            {!reducedMotion && !frozen && (
              <button
                type="button"
                onClick={() => setPaused(!paused)}
                aria-pressed={paused}
              >
                {paused ? "Animate model" : "Pause model"}
              </button>
            )}
            <button
              type="button"
              onClick={step}
              title="Advance the wave phase by 22.5 degrees"
            >
              Step +22.5°
            </button>
          </div>
        </div>
        <p className="air-model__explanation">
          {motionPaused ? "Paused for observation. " : ""}The wave travels; each
          marker stays near its own position. The ring marks the highlighted
          particle’s equilibrium.{" "}
          {amplitude === 0
            ? "At zero amplitude, there are no compressions or rarefactions."
            : ""}
        </p>
        <details className="air-model__science">
          <summary>How this model is scaled</summary>
          <p>
            ξ(x,t) = A cos(kx − ωt). Compression is proportional to −∂ξ/∂x = kA
            sin(kx − ωt). The span represents 2 m and the assumed sound speed is{" "}
            {SOUND_SPEED} m/s. Time runs {SLOW_MOTION_DIVISOR}× slower: one
            second on screen represents{" "}
            {(1000 / SLOW_MOTION_DIVISOR).toFixed(2)} ms. At 440 Hz, this is 2
            model cycles per second.
          </p>
          <p>
            Particle displacement is exaggerated and bounded so kA ≤ 0.42. Gain
            controls relative model amplitude, not a calibrated displacement in
            air. Marker size, spacing, and the speaker are illustrative.{" "}
            {waveform !== "sine"
              ? `The selected ${waveform} sound is simplified to its sinusoidal fundamental here.`
              : "This scene represents a sinusoidal plane wave."}{" "}
            This is not a measured image of air.
          </p>
        </details>
        <p className="visual-sr-only" id={descriptionId}>
          A longitudinal-wave illustration. Particle displacement is parallel to
          wave propagation, with particles oscillating about fixed equilibrium
          positions. Sound frequency {frequency} hertz, relative amplitude{" "}
          {Math.round(amplitude * 100)} percent, illustrative wavelength{" "}
          {parameters.wavelength.toFixed(2)} metres. Compression means closer
          markers. Rarefaction means wider spacing. The highlighted coral marker
          stays near its equilibrium ring. The model runs {SLOW_MOTION_DIVISOR}{" "}
          times slower than physical time, and can be paused or advanced by 22.5
          degree phase steps.
        </p>
      </figcaption>
    </figure>
  );
}

export default AirModel;
