import { useState } from "react";
import { engine } from "../audio/engine";
import { HARMONIC_PRESETS } from "../audio/presets";
import { knownHarmonicFundamental } from "../audio/dsp";
import { useSound } from "../useSound";
import { MeasurementPlot } from "../visuals/MeasurementPlot";
import { Icon } from "../components/Icon";
import { Investigation } from "../components/Investigation";
export function TimbreLab() {
  const s = useSound();
  const [mode, setMode] = useState<"waveform" | "spectrum">("spectrum");
  const [frozen, setFrozen] = useState(false);
  const [trialVersion, setTrialVersion] = useState(0);
  const reset = () => {
    engine.stop();
    engine.setTimbreFrequency(440);
    engine.setTimbre("a", HARMONIC_PRESETS[0].weights);
    engine.setTimbre("b", HARMONIC_PRESETS[2].weights);
    setFrozen(false);
    setTrialVersion((n) => n + 1);
  };
  return (
    <section className="laboratory timbre-lab" aria-labelledby="timbre-heading">
      <div className="lab-heading">
        <div>
          <div className="eyebrow">
            <span className="lab-number">02</span> THE TIMBRE STUDIO
          </div>
          <h2 id="timbre-heading">One note. Many personalities.</h2>
          <p>If the note stays the same, what makes a sound feel different?</p>
        </div>
        <button className="subtle-button reset-lab" onClick={reset}>
          <Icon name="reset" size={16} />
          Reset lab
        </button>
      </div>
      <div className="comparison-toolbar">
        <div className="common-note">
          <span>Shared base frequency</span>
          <div className="segmented">
            {[220, 440, 880].map((f) => (
              <button
                key={f}
                className={s.timbreFrequency === f ? "selected" : ""}
                aria-pressed={s.timbreFrequency === f}
                onClick={() => {
                  engine.setTimbreFrequency(f);
                  setFrozen(false);
                }}
              >
                {f} Hz
              </button>
            ))}
          </div>
        </div>
        <div className="segmented" aria-label="Comparison visualization">
          <button
            className={mode === "waveform" ? "selected" : ""}
            onClick={() => setMode("waveform")}
          >
            Waveform
          </button>
          <button
            className={mode === "spectrum" ? "selected" : ""}
            onClick={() => setMode("spectrum")}
          >
            Spectrum
          </button>
        </div>
        <button
          className="subtle-button"
          disabled={!s.activated}
          onClick={() => setFrozen(!frozen)}
          aria-pressed={frozen}
        >
          <Icon name={frozen ? "play" : "pause"} size={16} />
          {frozen ? "Unfreeze" : "Freeze both"}
        </button>
      </div>
      <div className="timbre-pair">
        {(["a", "b"] as const).map((side) => {
          const weights = side === "a" ? s.harmonicsA : s.harmonicsB;
          const norm = side === "a" ? s.normalizationA : s.normalizationB;
          const repetitionFrequency = knownHarmonicFundamental(
            weights,
            s.timbreFrequency,
          );
          const preset = HARMONIC_PRESETS.find((p) =>
            p.weights.every((w, i) => Math.abs(w - weights[i]) < 0.001),
          );
          const selected = s.activeSource === side;
          const playing = s.playing && selected;
          const audible = playing && !s.muted && s.volume > 0 && !norm.silent;
          const channelStatus = playing
            ? s.muted
              ? "Selected · muted"
              : s.volume === 0 || norm.silent
                ? "Selected · silent"
                : "Listening"
            : selected && s.activated
              ? "Paused"
              : "Listen";
          return (
            <article
              className={`timbre-channel channel-${side} ${audible ? "audible" : ""}`}
              key={side}
              aria-label={`Sound ${side.toUpperCase()}`}
            >
              <div className="channel-header">
                <span className="channel-letter">{side.toUpperCase()}</span>
                <div>
                  <h3>{preset?.name ?? "Your own mixture"}</h3>
                  <span>Harmonic synthesis</span>
                </div>
                <button
                  className={`channel-play ${audible ? "playing" : ""}`}
                  aria-label={`${playing ? "Pause" : "Play"} sound ${side.toUpperCase()}`}
                  onClick={() =>
                    playing ? engine.pause() : void engine.play(side)
                  }
                >
                  <Icon name={playing ? "pause" : "play"} />
                  <span>{channelStatus}</span>
                </button>
                <button
                  className="icon-button"
                  aria-label={`Stop sound ${side.toUpperCase()}`}
                  onClick={() => engine.stop()}
                >
                  <Icon name="stop" size={16} />
                </button>
              </div>
              {playing && !audible && (
                <p className="measurement-note" role="status">
                  {s.muted
                    ? "This channel is selected, but master listening is muted."
                    : s.volume === 0
                      ? "This channel is selected with listening volume at 0%."
                      : "This channel is selected, but all six harmonic weights are zero."}
                </p>
              )}
              <label className="preset-select">
                Sound character
                <select
                  aria-label={`Sound ${side.toUpperCase()} preset`}
                  value={preset?.id ?? "custom"}
                  onChange={(e) => {
                    const p = HARMONIC_PRESETS.find(
                      (p) => p.id === e.target.value,
                    );
                    if (p) {
                      engine.setTimbre(side, p.weights);
                      setFrozen(false);
                    }
                  }}
                >
                  <option value="custom" disabled>
                    Custom mixture
                  </option>
                  {HARMONIC_PRESETS.map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.name}
                    </option>
                  ))}
                </select>
              </label>
              <div className="channel-plot">
                <MeasurementPlot
                  source={side}
                  mode={mode}
                  frozen={frozen}
                  frequency={repetitionFrequency}
                  timeWindow={10}
                  color={side === "a" ? "#287c83" : "#b25b43"}
                  compact
                  label={`Sound ${side.toUpperCase()} measured ${mode}`}
                />
              </div>
              <div className="harmonic-section">
                <div className="harmonic-heading">
                  <strong>Mix the harmonics</strong>
                  <span>Relative weights · before level matching</span>
                </div>
                <div className="harmonic-faders">
                  {weights.map((weight, i) => (
                    <label className="harmonic-fader" key={i}>
                      <span className="fader-value">
                        {Math.round(weight * 100)}
                        <small>%</small>
                      </span>
                      <input
                        type="range"
                        min="0"
                        max="100"
                        step="1"
                        value={Math.round(weight * 100)}
                        aria-label={`Sound ${side.toUpperCase()} harmonic ${i + 1}`}
                        onChange={(e) => {
                          const next = [...weights];
                          next[i] = Number(e.target.value) / 100;
                          engine.setTimbre(side, next);
                        }}
                      />
                      <strong>H{i + 1}</strong>
                      <span>
                        {s.timbreFrequency * (i + 1)}
                        <small> Hz</small>
                      </span>
                    </label>
                  ))}
                </div>
              </div>
              <div className="normalization-note">
                <span className={`status-dot ${norm.silent ? "" : "active"}`} />
                {norm.silent
                  ? "All harmonics at zero: this source is silent."
                  : norm.limited
                    ? "Peak protection lowered the RMS target."
                    : `RMS target ${norm.rms.toFixed(3)} · digital level matching on`}
              </div>
              {repetitionFrequency &&
                repetitionFrequency !== s.timbreFrequency && (
                  <p className="harmonic-pitch-note">
                    These harmonics repeat at {repetitionFrequency} Hz. The
                    pitch can change when lower harmonics are removed.
                  </p>
                )}
            </article>
          );
        })}
      </div>
      <div className="timbre-explanation">
        <Icon name="music" size={28} />
        <div>
          <h3>Timbre is a recipe, not just a note.</h3>
          <p>
            These are original synthesized balances, not instrument recordings.
            Real instruments also change through time: their attack, decay,
            noise and resonances help create their character.
          </p>
        </div>
        <span className="paper-tag">
          Same f₀
          <br />
          Different harmonics
        </span>
      </div>
      <p className="measurement-note">
        Each channel is measured before its listening gate. Both signals remain
        visible during A/B listening. Matching digital RMS helps comparison; it
        does not guarantee equal perceived loudness.
      </p>
      <Investigation
        key={trialVersion}
        kind="timbre"
        onSetup={() => setFrozen(false)}
      />
    </section>
  );
}
