import { useEffect, useId, useState, useSyncExternalStore } from "react";
import { engine } from "../audio/engine";
import "./education.css";

export type InvestigationKind = "amplitude" | "frequency" | "timbre";
interface InvestigationProps {
  kind: InvestigationKind;
  onSetup?: (kind: InvestigationKind) => void;
}
type Stage = "predict" | "test" | "ready" | "explain";
const PURE = [1, 0, 0, 0, 0, 0];
const ODD = [1, 0, 0.333, 0, 0.2, 0];
const SETTLE_MS = 450;
const same = (a: readonly number[], b: readonly number[]) =>
  a.length === b.length &&
  a.every((value, index) => Math.abs(value - b[index]) < 0.0001);
const near = (a: number, b: number) => Math.abs(a - b) < 0.0001;

const LESSONS = {
  amplitude: {
    title: "Turn it up. Does the note change?",
    question: "If you double amplitude, what happens to the pitch?",
    options: [
      "Pitch stays the same",
      "Pitch becomes higher",
      "Pitch becomes lower",
    ],
    correct: 0,
    controls: "Change amplitude · Keep 440 Hz and sine fixed",
    instruction:
      "Use the amplitude knob or number field to change 25% → 50%. Keep listening and watch the trace.",
    explanation:
      "You doubled the signal amplitude while frequency stayed at 440 Hz. The trace grew taller and the pitch stayed the same. The comparable digital signal level increased by 20 log₁₀(2) ≈ 6.02 dB. That does not mean twice the perceived loudness, and this percentage is not a measurement of sound pressure level.",
  },
  frequency: {
    title: "Same amplitude. A different note.",
    question: "What will doubling frequency from 220 Hz to 440 Hz change?",
    options: [
      "The waveform height doubles",
      "The pitch rises by one octave",
      "The note becomes lower",
    ],
    correct: 1,
    controls: "Change frequency · Keep 30% amplitude and sine fixed",
    instruction:
      "Use the frequency knob, number field or preset to change 220 Hz → 440 Hz. Keep the same time window.",
    explanation:
      "At 440 Hz, the source makes twice as many cycles each second as at 220 Hz. You hear a note one octave higher; at the same time window, you see twice as many cycles. Configured gain stays at 30%. Equal digital amplitude does not guarantee equal perceived loudness at different frequencies.",
  },
  timbre: {
    title: "One note. Two personalities.",
    question: "Can two sounds at 440 Hz have different sound characters?",
    options: [
      "No, the frequency decides everything",
      "Yes, their harmonics can differ",
      "Only if one changes its pitch",
    ],
    correct: 1,
    controls: "Compare harmonic balance · Keep the fundamental at 440 Hz",
    instruction:
      "Listen to A, then use the B listening control. Compare the two waveforms and spectra.",
    explanation:
      "Both mixtures have a 440 Hz fundamental. A contains only that frequency; B also contains the third and fifth harmonics. Their harmonic balances change the waveform and the timbre. RMS matching helps compare signal levels, but equal RMS is not equal perceived loudness. Real instruments also have attacks, decays, noise and changing spectra.",
  },
} as const;

export function Investigation({ kind, onSetup }: InvestigationProps) {
  const state = useSyncExternalStore(
    engine.subscribe,
    engine.getSnapshot,
    engine.getSnapshot,
  );
  const [prediction, setPrediction] = useState<number | null>(null);
  const [stage, setStage] = useState<Stage>("predict");
  const [baselineHeard, setBaselineHeard] = useState(false);
  const [heardA, setHeardA] = useState(false);
  const [heardB, setHeardB] = useState(false);
  const [invalid, setInvalid] = useState(false);
  const [starting, setStarting] = useState(false);
  const id = useId();
  const lesson = LESSONS[kind];

  useEffect(() => {
    setPrediction(null);
    setStage("predict");
    setBaselineHeard(false);
    setHeardA(false);
    setHeardB(false);
    setInvalid(false);
  }, [kind]);

  async function begin() {
    if (prediction === null || starting) return;
    setStarting(true);
    setInvalid(false);
    setBaselineHeard(false);
    setHeardA(false);
    setHeardB(false);
    if (kind === "timbre") {
      engine.setTimbreFrequency(440);
      engine.setTimbre("a", PURE);
      engine.setTimbre("b", ODD);
    } else {
      engine.setTone({
        frequency: kind === "amplitude" ? 440 : 220,
        amplitude: kind === "amplitude" ? 0.25 : 0.3,
        waveform: "sine",
      });
    }
    onSetup?.(kind);
    setStage("test");
    try {
      await engine.play(kind === "timbre" ? "a" : "tone");
    } finally {
      setStarting(false);
    }
  }

  const {
    playing,
    muted,
    volume,
    activeSource,
    frequency,
    amplitude,
    waveform,
    timbreFrequency,
    harmonicsA,
    harmonicsB,
  } = state;
  const canListen = playing && !muted && volume > 0;

  // Settings must settle while an audible listening path is open. A click alone is not evidence.
  // Depend on relevant settings, not the whole snapshot: an imported-file clock can update at 4 Hz.
  useEffect(() => {
    if (stage !== "test" || invalid || starting) return;
    const controlledOkay =
      kind === "amplitude"
        ? frequency === 440 && waveform === "sine"
        : kind === "frequency"
          ? near(amplitude, 0.3) && waveform === "sine"
          : timbreFrequency === 440 &&
            same(harmonicsA, PURE) &&
            same(harmonicsB, ODD);
    if (!controlledOkay) {
      setInvalid(true);
      return;
    }
    if (!canListen) return;
    if (kind === "timbre") {
      if (activeSource !== "a" && activeSource !== "b") return;
      const observedSide = activeSource;
      const timer = window.setTimeout(() => {
        const current = engine.getSnapshot();
        if (
          !current.playing ||
          current.muted ||
          current.volume <= 0 ||
          current.activeSource !== observedSide
        )
          return;
        if (observedSide === "a") setHeardA(true);
        else setHeardB(true);
      }, SETTLE_MS);
      return () => clearTimeout(timer);
    }
    if (activeSource !== "tone") return;
    const isBaseline =
      kind === "amplitude" ? near(amplitude, 0.25) : frequency === 220;
    const isTarget =
      kind === "amplitude" ? near(amplitude, 0.5) : frequency === 440;
    if ((!baselineHeard && !isBaseline) || (baselineHeard && !isTarget)) return;
    const timer = window.setTimeout(() => {
      const current = engine.getSnapshot();
      if (
        !current.playing ||
        current.muted ||
        current.volume <= 0 ||
        current.activeSource !== "tone"
      )
        return;
      if (!baselineHeard) setBaselineHeard(true);
      else setStage("ready");
    }, SETTLE_MS);
    return () => clearTimeout(timer);
  }, [
    stage,
    kind,
    invalid,
    starting,
    canListen,
    activeSource,
    frequency,
    amplitude,
    waveform,
    timbreFrequency,
    harmonicsA,
    harmonicsB,
    baselineHeard,
  ]);

  useEffect(() => {
    if (stage === "test" && kind === "timbre" && heardA && heardB && !invalid)
      setStage("ready");
  }, [stage, kind, heardA, heardB, invalid]);

  let status = "Choose a prediction, then begin the experiment.";
  if (stage === "test") {
    if (invalid)
      status =
        "A controlled setting changed. Begin again for a fair comparison.";
    else if (muted)
      status =
        "Listening is muted. Unmute when you are ready to compare the sounds.";
    else if (volume === 0)
      status =
        "Increase listening volume slightly to make the comparison audible.";
    else if (!playing || (kind !== "timbre" && activeSource !== "tone"))
      status = "Press Play for this experiment to continue listening.";
    else if (kind === "timbre")
      status = heardA
        ? "A observed. Now listen to B for a moment."
        : "Listen to the starting A mixture for a moment, then compare B.";
    else if (!baselineHeard)
      status =
        kind === "amplitude"
          ? "First listen at 25% amplitude for a moment. Return to 25% if you already moved the control."
          : "First listen at 220 Hz for a moment. Return to 220 Hz if you already moved the control.";
    else status = lesson.instruction;
  } else if (stage === "ready")
    status = "Comparison recorded. You can now reveal the explanation.";

  return (
    <section
      className={`investigation edu-${kind}`}
      aria-labelledby={`${id}-title`}
    >
      <div className="investigation-intro">
        <span className="edu-eyebrow">A small experiment</span>
        <h3 id={`${id}-title`}>{lesson.title}</h3>
        <p>{lesson.controls}</p>
        <ol className="investigation-steps" aria-label="Investigation progress">
          {(["Predict", "Test", "Explain"] as const).map((name, index) => (
            <li
              key={name}
              className={
                (stage === "predict"
                  ? 0
                  : stage === "test" || stage === "ready"
                    ? 1
                    : 2) === index
                  ? "current"
                  : ""
              }
            >
              <span>{index + 1}</span>
              {name}
            </li>
          ))}
        </ol>
      </div>
      <div className="investigation-work">
        {stage === "predict" ? (
          <>
            <fieldset className="prediction-fieldset">
              <legend>{lesson.question}</legend>
              <div className="prediction-options">
                {lesson.options.map((option, index) => (
                  <label
                    key={option}
                    className={prediction === index ? "selected" : ""}
                  >
                    <input
                      type="radio"
                      name={`${id}-prediction`}
                      checked={prediction === index}
                      onChange={() => setPrediction(index)}
                    />
                    <span>{option}</span>
                  </label>
                ))}
              </div>
            </fieldset>
            <button
              type="button"
              className="edu-primary"
              disabled={prediction === null || starting}
              onClick={() => void begin()}
            >
              Begin test <span aria-hidden="true">→</span>
            </button>
          </>
        ) : stage === "explain" ? (
          <>
            <p className="investigation-observed">
              {prediction === lesson.correct
                ? "Your prediction matched the observation."
                : "Use the observation to revisit your prediction."}
            </p>
            <p className="investigation-explanation">{lesson.explanation}</p>
            <button
              type="button"
              className="edu-text-button"
              onClick={() => {
                setStage("predict");
                setPrediction(null);
              }}
            >
              Try another prediction <span aria-hidden="true">↗</span>
            </button>
          </>
        ) : (
          <>
            <p className="committed-prediction">
              Your prediction:{" "}
              <strong>
                {prediction !== null ? lesson.options[prediction] : ""}
              </strong>
            </p>
            <p
              className={`experiment-status${invalid ? " invalid" : ""}`}
              role="status"
              aria-live="polite"
            >
              {status}
            </p>
            {kind === "timbre" && (
              <p className="listening-evidence">
                <span>{heardA ? "✓" : "○"} A observed</span>
                <span>{heardB ? "✓" : "○"} B observed</span>
              </p>
            )}
            <div className="investigation-actions">
              <button
                type="button"
                className="edu-primary"
                disabled={stage !== "ready"}
                onClick={() => setStage("explain")}
              >
                Reveal explanation
              </button>
              <button
                type="button"
                className="edu-text-button"
                disabled={starting}
                onClick={() => void begin()}
              >
                Begin again
              </button>
            </div>
          </>
        )}
      </div>
    </section>
  );
}
