import { useState } from "react";
import { engine } from "../audio/engine";
import { CABINET_SOUNDS } from "../audio/presets";
import { useSound } from "../useSound";
import { MeasurementPlot } from "../visuals/MeasurementPlot";
import { Icon } from "./Icon";
const pictures: Record<string, string> = {
  tone: "M12 4v12M8 4v6a4 4 0 0 0 8 0V4M8 20h8",
  harmonic: "M4 15V9M8 18V6M12 21V3M16 17V7M20 14v-4",
  bell: "M5 17h14l-2-4V9a5 5 0 0 0-10 0v4ZM10 20h4M12 2v2",
  knock: "M3 9h18v11H3ZM6 13h12M14 3l-4 6M13 2l3 2",
  clock:
    "M12 7v5l4 2M7 3 3 6M17 3l4 3M7 20l-1 2M17 20l1 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0",
  drop: "M12 2C8 9 5 11 5 15a7 7 0 0 0 14 0c0-4-3-6-7-13ZM9 15a3 3 0 0 0 3 3",
  whistle:
    "M3 10h8l5-5h5v7h-6a6 6 0 1 1-12-2ZM7 13a2 2 0 1 0 0 4 2 2 0 0 0 0-4",
  spark: "m12 2 2 7 7 3-7 3-2 7-2-7-7-3 7-3Z",
};
export function SoundCabinet() {
  const s = useSound();
  const [selected, setSelected] = useState<string | null>(null);
  const [mode, setMode] = useState<"waveform" | "spectrum">("waveform");
  const [frozen, setFrozen] = useState(false);
  const sound = CABINET_SOUNDS.find((x) => x.id === selected);
  return (
    <section className="sound-cabinet" aria-labelledby="cabinet-heading">
      <div className="cabinet-heading">
        <div>
          <span className="eyebrow">THE SOUND CABINET</span>
          <h2 id="cabinet-heading">Small sounds. Big discoveries.</h2>
          <p>
            Open a drawer of original sounds, made from a little mathematics.
          </p>
        </div>
        <span className="cabinet-stamp">
          Made to
          <br />
          <strong>be heard.</strong>
        </span>
      </div>
      <div className="cabinet-shelf">
        {CABINET_SOUNDS.map((item, i) => (
          <button
            key={item.id}
            className={`cabinet-item tint-${i % 5} ${selected === item.id ? "selected" : ""}`}
            aria-pressed={
              selected === item.id && s.playing && s.activeSource === "cabinet"
            }
            onClick={() => {
              setSelected(item.id);
              setFrozen(false);
              void engine.playCabinet(item.id);
            }}
          >
            <span className="cabinet-object">
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
                aria-hidden="true"
              >
                <path d={pictures[item.symbol] ?? pictures.tone} />
              </svg>
              <i>
                <Icon name="play" size={11} />
              </i>
            </span>
            <strong>{item.name}</strong>
            <small>{item.duration.toFixed(1)} s · synthesized</small>
          </button>
        ))}
      </div>
      {sound && (
        <div className="cabinet-inspector">
          <div className="cabinet-inspector-top">
            <div>
              <strong>{sound.name}</strong>
              <p>{sound.observation}</p>
              <small>{sound.category} · Original procedural audio</small>
            </div>
            <div className="cabinet-listen-controls">
              <button
                className="subtle-button"
                onClick={() => {
                  setFrozen(false);
                  void engine.playCabinet(sound.id);
                }}
              >
                <Icon name="play" size={15} />
                Replay
              </button>
              <button
                className="icon-button"
                aria-label="Stop cabinet sound"
                onClick={() => engine.stop()}
              >
                <Icon name="stop" size={16} />
              </button>
              <button
                className="icon-button"
                aria-label="Close cabinet measurement"
                onClick={() => {
                  if (s.activeSource === "cabinet") engine.stop();
                  setSelected(null);
                }}
              >
                <Icon name="close" size={16} />
              </button>
            </div>
          </div>
          <div className="scope-toolbar">
            <div className="segmented">
              <button
                className={mode === "waveform" ? "selected" : ""}
                onClick={() => setMode("waveform")}
              >
                Waveform
              </button>
              <button
                className={mode === "spectrum" ? "selected" : ""}
                onClick={() => setMode("spectrum")}
              >
                Spectrum
              </button>
            </div>
            <button
              className="subtle-button"
              aria-pressed={frozen}
              onClick={() => setFrozen(!frozen)}
            >
              <Icon name={frozen ? "play" : "pause"} size={15} />
              {frozen ? "Unfreeze" : "Freeze"}
            </button>
          </div>
          <MeasurementPlot
            source="cabinet"
            mode={mode}
            compact
            frozen={frozen}
            timeWindow={20}
            frequency={sound.fundamental}
            label="Sound cabinet measured signal"
          />
          <p className="fineprint">
            Short sounds leave the display when their signal decays. Replay and
            freeze to inspect a captured moment.
          </p>
        </div>
      )}
    </section>
  );
}
