import { useEffect, useId, useRef, useState } from "react";
import { engine, type SourceId } from "../audio/engine";
import {
  binFrequency,
  digitalLevel,
  rms,
  strongestBin,
  triggerStart,
} from "./science";
import "./visuals.css";

export interface MeasurementPlotProps {
  source: SourceId;
  mode: "waveform" | "spectrum";
  frozen?: boolean;
  /** Requested visible time span in milliseconds. */
  timeWindow?: number;
  /** Known configured fundamental, never an estimate for an arbitrary file. */
  frequency?: number;
  color?: string;
  compact?: boolean;
  label?: string;
}

interface Capture {
  waveform: Float32Array<ArrayBuffer>;
  spectrum: Float32Array<ArrayBuffer>;
  sampleRate: number;
  fftSize: number;
  source: SourceId;
  frequency?: number;
  window: number;
  trigger: number;
  triggered: boolean;
  rms: number;
  peak: number;
  spectralPeak: ReturnType<typeof strongestBin>;
  smoothing: number;
}

interface Readout {
  ready: boolean;
  rms: number;
  peak: number;
  spectralPeak: number | null;
  resolution: number;
  sampleRate: number;
  fftSize: number;
  timeWindow: number;
  frequency?: number;
  source: SourceId;
  triggered: boolean;
  outsideScale: boolean;
  smoothing: number;
}

const EMPTY: Readout = {
  ready: false,
  rms: 0,
  peak: 0,
  spectralPeak: null,
  resolution: 0,
  sampleRate: 0,
  fftSize: 0,
  timeWindow: 10,
  source: "tone",
  triggered: false,
  outsideScale: false,
  smoothing: 0,
};
const names: Record<SourceId, string> = {
  tone: "Tone oscillator",
  a: "Harmonic source A",
  b: "Harmonic source B",
  file: "Local audio",
  cabinet: "Sound cabinet",
};
const hz = (f: number) =>
  f >= 1000
    ? `${(f / 1000).toFixed(f % 1000 === 0 ? 0 : 1)}k`
    : String(Math.round(f));
const decimal = (n: number, places = 1) =>
  Number.isFinite(n) ? n.toFixed(places) : "−∞";

function copyCapture(capture: Capture): Capture {
  return {
    ...capture,
    waveform: new Float32Array(capture.waveform),
    spectrum: new Float32Array(capture.spectrum),
    spectralPeak: capture.spectralPeak ? { ...capture.spectralPeak } : null,
  };
}

function readout(capture: Capture): Readout {
  return {
    ready: true,
    rms: capture.rms,
    peak: capture.peak,
    spectralPeak: capture.spectralPeak?.frequency ?? null,
    resolution: capture.sampleRate / capture.fftSize,
    sampleRate: capture.sampleRate,
    fftSize: capture.fftSize,
    timeWindow: capture.window,
    frequency: capture.frequency,
    source: capture.source,
    triggered: capture.triggered,
    outsideScale: capture.peak > 1,
    smoothing: capture.smoothing,
  };
}

export function MeasurementPlot({
  source,
  mode,
  frozen = false,
  timeWindow = 10,
  frequency,
  color = "#287C83",
  compact = false,
  label,
}: MeasurementPlotProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hostRef = useRef<HTMLDivElement>(null);
  const liveRef = useRef<Capture | null>(null);
  const heldRef = useRef<Capture | null>(null);
  const wasFrozen = useRef(false);
  const dimensions = useRef({
    width: 600,
    height: compact ? 178 : 278,
    dpr: 1,
  });
  const propsRef = useRef({
    source,
    mode,
    frozen,
    timeWindow,
    frequency,
    color,
    compact,
  });
  propsRef.current = {
    source,
    mode,
    frozen,
    timeWindow,
    frequency,
    color,
    compact,
  };
  const [values, setValues] = useState<Readout>({
    ...EMPTY,
    source,
    timeWindow,
  });
  const descriptionId = useId();

  useEffect(() => {
    if (frozen && !wasFrozen.current)
      heldRef.current = liveRef.current ? copyCapture(liveRef.current) : null;
    if (!frozen) heldRef.current = null;
    wasFrozen.current = frozen;
    const captured = frozen ? heldRef.current : liveRef.current;
    if (captured) setValues(readout(captured));
  }, [frozen]);

  useEffect(() => {
    // A capture belongs to its source. Switching sources while frozen leaves a
    // blank, explicitly uncaptured view until Unfreeze, never an old source trace.
    liveRef.current = null;
    heldRef.current = null;
    setValues({ ...EMPTY, source, timeWindow: propsRef.current.timeWindow });
  }, [source]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const host = hostRef.current;
    if (!canvas || !host) return;
    const context = canvas.getContext("2d");
    if (!context) return;
    let raf = 0;
    let lastReadout = 0;
    let lastDraw = 0;
    let disposed = false;
    let previousSourceIdentity: string | null = null;

    function resize() {
      if (!canvas || !host) return;
      const bounds = host.getBoundingClientRect();
      const width = Math.max(180, bounds.width);
      const height = Math.max(130, bounds.height);
      const dpr = Math.min(3, window.devicePixelRatio || 1);
      dimensions.current = { width, height, dpr };
      canvas.width = Math.round(width * dpr);
      canvas.height = Math.round(height * dpr);
      draw(propsRef.current.frozen ? heldRef.current : liveRef.current);
    }

    function acquire(): Capture | null {
      const props = propsRef.current;
      const analyser = engine.getAnalyser(props.source);
      if (!analyser) return null;
      const sampleRate = analyser.context.sampleRate;
      const fftSize = analyser.fftSize;
      let capture = liveRef.current;
      if (
        !capture ||
        capture.waveform.length !== fftSize ||
        capture.source !== props.source
      ) {
        capture = {
          waveform: new Float32Array(fftSize),
          spectrum: new Float32Array(analyser.frequencyBinCount),
          sampleRate,
          fftSize,
          source: props.source,
          frequency: props.frequency,
          window: props.timeWindow,
          trigger: 0,
          triggered: false,
          rms: 0,
          peak: 0,
          spectralPeak: null,
          smoothing: analyser.smoothingTimeConstant,
        };
      }
      analyser.getFloatTimeDomainData(capture.waveform);
      analyser.getFloatFrequencyData(capture.spectrum);
      capture.sampleRate = sampleRate;
      capture.fftSize = fftSize;
      capture.smoothing = analyser.smoothingTimeConstant;
      capture.frequency = props.frequency;
      capture.window = Math.min(
        props.timeWindow,
        ((fftSize - 1) * 1000) / sampleRate,
      );
      const sampleCount = Math.floor((capture.window / 1000) * sampleRate) + 1;
      const trigger =
        props.source === "file" || props.source === "cabinet"
          ? { index: Math.max(0, fftSize - sampleCount), triggered: false }
          : triggerStart(capture.waveform, sampleCount);
      capture.trigger = trigger.index;
      capture.triggered = trigger.triggered;
      capture.rms = rms(capture.waveform);
      let peak = 0;
      for (let i = 0; i < capture.waveform.length; i++)
        peak = Math.max(peak, Math.abs(capture.waveform[i]));
      capture.peak = peak;
      capture.spectralPeak = strongestBin(
        capture.spectrum,
        sampleRate,
        fftSize,
      );
      liveRef.current = capture;
      return capture;
    }

    function draw(capture: Capture | null) {
      if (!context) return;
      const { width: w, height: h, dpr } = dimensions.current;
      const props = propsRef.current;
      const isWave = props.mode === "waveform";
      const narrow = w < 400;
      const presentation = !!host?.closest(".presentation") && w >= 480;
      const margin = presentation
        ? { left: 64, right: 20, top: 40, bottom: 50 }
        : { left: narrow ? 40 : 49, right: 16, top: 29, bottom: 37 };
      const left = margin.left;
      const top = margin.top;
      const width = w - left - margin.right;
      const height = h - top - margin.bottom;
      const span = capture?.window ?? props.timeWindow;
      const maxHz = Math.min(6000, (capture?.sampleRate ?? 48000) / 2);
      context.setTransform(dpr, 0, 0, dpr, 0, 0);
      context.clearRect(0, 0, w, h);
      context.fillStyle = "#FBF9F3";
      context.fillRect(0, 0, w, h);
      context.font = `${presentation ? 16 : props.compact ? 10 : 11}px system-ui, sans-serif`;
      context.lineWidth = 1;
      context.textBaseline = "middle";

      // Scientific grid: fixed ±1 digital amplitude, or fixed −100…0 spectral dB.
      const ticks = isWave ? [1, 0.5, 0, -0.5, -1] : [0, -25, -50, -75, -100];
      for (let i = 0; i < ticks.length; i++) {
        const y = top + (i / (ticks.length - 1)) * height;
        context.strokeStyle = isWave && ticks[i] === 0 ? "#A6B3AC" : "#E5E6DD";
        context.beginPath();
        context.moveTo(left, y + 0.5);
        context.lineTo(left + width, y + 0.5);
        context.stroke();
        context.fillStyle = "#53645F";
        context.textAlign = "right";
        context.fillText(
          isWave
            ? ticks[i] > 0
              ? `+${ticks[i]}`
              : String(ticks[i])
            : String(ticks[i]),
          left - 8,
          y,
        );
      }
      const xTickCount = narrow ? 4 : 5;
      for (let i = 0; i <= xTickCount; i++) {
        const x = left + (i / xTickCount) * width;
        context.strokeStyle = "#E5E6DD";
        context.beginPath();
        context.moveTo(x + 0.5, top);
        context.lineTo(x + 0.5, top + height);
        context.stroke();
        context.fillStyle = "#53645F";
        context.textAlign =
          i === 0 ? "left" : i === xTickCount ? "right" : "center";
        const value = isWave
          ? (span * i) / xTickCount
          : (maxHz * i) / xTickCount;
        context.fillText(
          isWave ? `${Number(value.toFixed(2))}` : hz(value),
          x,
          top + height + (presentation ? 18 : 13),
        );
      }
      context.textAlign = "left";
      context.fillStyle = "#475952";
      context.fillText(
        isWave
          ? narrow
            ? "Digital amplitude"
            : "Normalized digital amplitude"
          : "Digital spectral level (dB)",
        left,
        presentation ? 18 : 13,
      );
      context.textAlign = "right";
      context.fillText(
        isWave ? "Time (ms)" : "Frequency (Hz)",
        left + width,
        h - (presentation ? 10 : 6),
      );

      if (!capture) {
        context.fillStyle = "#546660";
        context.textAlign = "center";
        context.font = `500 ${presentation ? 17 : narrow ? 12 : 14}px system-ui, sans-serif`;
        const line = props.frozen
          ? "No capture yet. Unfreeze to measure."
          : "Start audio to see a real measurement";
        const textWidth = context.measureText(line).width;
        context.fillStyle = "rgba(251,249,243,.94)";
        context.fillRect(
          left + width / 2 - textWidth / 2 - 10,
          top + height / 2 - 17,
          textWidth + 20,
          34,
        );
        context.fillStyle = "#546660";
        context.fillText(line, left + width / 2, top + height / 2);
        return;
      }

      context.save();
      context.beginPath();
      context.rect(left, top - 1, width, height + 2);
      context.clip();
      if (!isWave && capture.frequency) {
        const f0 = capture.frequency;
        context.lineWidth = 1;
        context.setLineDash([3, 4]);
        for (let harmonic = 1; harmonic <= 6; harmonic++) {
          const frequency = harmonic * f0;
          if (frequency > maxHz) break;
          const x = left + (frequency / maxHz) * width;
          context.strokeStyle = harmonic === 1 ? "#A9792C" : "#C9BEA6";
          context.beginPath();
          context.moveTo(x, top);
          context.lineTo(x, top + height);
          context.stroke();
          if (
            !props.compact &&
            width > 360 &&
            (!presentation || (f0 / maxHz) * width >= 32 || harmonic === 1)
          ) {
            context.fillStyle = harmonic === 1 ? "#866022" : "#7B7669";
            context.textAlign = "center";
            context.font = `${presentation ? 14 : 10}px system-ui, sans-serif`;
            context.fillText(
              harmonic === 1 ? "f₀" : `${harmonic}f₀`,
              x,
              top + (presentation ? 13 : 9),
            );
          }
        }
        context.setLineDash([]);
      }
      context.strokeStyle = props.color;
      context.lineWidth = props.compact ? 1.7 : 2.25;
      context.lineJoin = "round";
      context.lineCap = "round";
      context.beginPath();
      if (isWave) {
        const end = Math.min(
          capture.waveform.length - 1,
          capture.trigger + Math.floor((span / 1000) * capture.sampleRate),
        );
        for (let i = capture.trigger; i <= end; i++) {
          const x =
            left +
            ((i - capture.trigger) / capture.sampleRate / (span / 1000)) *
              width;
          const y = top + ((1 - capture.waveform[i]) / 2) * height;
          if (i === capture.trigger) context.moveTo(x, y);
          else context.lineTo(x, y);
        }
      } else {
        const endBin = Math.min(
          capture.spectrum.length - 1,
          Math.ceil((maxHz * capture.fftSize) / capture.sampleRate),
        );
        for (let i = 0; i <= endBin; i++) {
          const x =
            left +
            (binFrequency(i, capture.sampleRate, capture.fftSize) / maxHz) *
              width;
          const value = Number.isFinite(capture.spectrum[i])
            ? capture.spectrum[i]
            : -150;
          const y = top + (Math.max(0, Math.min(100, -value)) / 100) * height;
          if (i === 0) context.moveTo(x, y);
          else context.lineTo(x, y);
        }
      }
      context.stroke();
      context.restore();
    }

    function loop(now: number) {
      if (disposed || document.hidden) return;
      const props = propsRef.current;
      if (now - lastDraw >= 16) {
        const currentState = engine.getSnapshot();
        // Replacing a local file reuses its analyser port, but is a new source.
        // The creation counter distinguishes even two files with identical names.
        const sourceIdentity =
          props.source === "file"
            ? `file:${engine.getDiagnostics().objectUrlsCreated}:${currentState.file ? "present" : "removed"}`
            : props.source === "cabinet"
              ? `cabinet:${currentState.cabinetId ?? ""}`
              : props.source;
        if (
          previousSourceIdentity !== null &&
          previousSourceIdentity !== sourceIdentity
        ) {
          liveRef.current = null;
          heldRef.current = null;
        }
        previousSourceIdentity = sourceIdentity;
        const capture = props.frozen ? heldRef.current : acquire();
        draw(capture);
        if (now - lastReadout > 240) {
          setValues(
            capture
              ? readout(capture)
              : {
                  ...EMPTY,
                  source: props.source,
                  timeWindow: props.timeWindow,
                },
          );
          lastReadout = now;
        }
        lastDraw = now;
      }
      raf = requestAnimationFrame(loop);
    }

    function onVisibility() {
      cancelAnimationFrame(raf);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    }
    const observer = new ResizeObserver(resize);
    observer.observe(host);
    resize();
    document.addEventListener("visibilitychange", onVisibility);
    if (!document.hidden) raf = requestAnimationFrame(loop);
    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      observer.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, []);

  const level = digitalLevel(values.rms);
  const sourceName = names[values.ready ? values.source : source];
  const shownWindow = values.ready ? values.timeWindow : timeWindow;
  const descriptor =
    mode === "waveform"
      ? `Measured waveform of ${sourceName}. Fixed vertical scale minus one to plus one normalized digital amplitude. Horizontal window ${decimal(shownWindow, 2)} milliseconds. ${values.ready ? `RMS ${decimal(values.rms, 3)}, digital RMS level ${decimal(level)} dBFS, peak amplitude ${decimal(values.peak, 3)}.` : "No samples captured yet."}`
      : `Measured frequency spectrum of ${sourceName}. Frequency range 0 to ${Math.min(6000, (values.sampleRate || 48000) / 2)} hertz. Vertical digital spectral level from minus 100 to zero decibels. ${values.ready ? `Frequency-bin spacing ${decimal(values.resolution, 2)} hertz. Strongest non-DC bin ${values.spectralPeak === null ? "not detected" : decimal(values.spectralPeak) + " hertz"}.` : "No samples captured yet."} ${values.frequency ? `Configured fundamental ${values.frequency} hertz; dashed lines mark its harmonics.` : "A spectral peak is not necessarily a fundamental."}`;

  return (
    <figure
      className={`measurement-plot ${compact ? "measurement-plot--compact" : ""}`}
      aria-label={label ?? `${sourceName} ${mode}`}
    >
      <div className="measurement-plot__status">
        <span
          className={`measurement-dot ${frozen ? "measurement-dot--frozen" : ""}`}
          aria-hidden="true"
        />
        <span>
          {frozen
            ? "Captured signal"
            : values.ready
              ? "Live measurement"
              : "Ready to measure"}
        </span>
        <span className="measurement-plot__scale">
          {mode === "waveform"
            ? `${Number(shownWindow.toFixed(2))} ms · fixed scale`
            : `0–${Math.min(6000, (values.sampleRate || 48000) / 2).toLocaleString()} Hz`}
        </span>
      </div>
      <div className="measurement-plot__canvas" ref={hostRef}>
        <canvas
          ref={canvasRef}
          role="img"
          aria-describedby={descriptionId}
          aria-label={label ?? `${sourceName}: measured ${mode}`}
        >
          {descriptor}
        </canvas>
      </div>
      <figcaption className="measurement-plot__caption">
        <div className="measurement-readouts" aria-hidden="true">
          <span>
            <span className="measurement-readouts__label">RMS</span>{" "}
            <strong>{values.ready ? decimal(values.rms, 3) : "—"}</strong>
          </span>
          <span>
            <span className="measurement-readouts__label">Signal level</span>{" "}
            <strong>{values.ready ? `${decimal(level)} dBFS` : "—"}</strong>
          </span>
          {mode === "spectrum" ? (
            <span>
              <span className="measurement-readouts__label">Strongest bin</span>{" "}
              <strong>
                {values.spectralPeak === null
                  ? "—"
                  : `${decimal(values.spectralPeak)} Hz${values.spectralPeak > 6000 ? " (beyond view)" : ""}`}
              </strong>
            </span>
          ) : (
            <span>
              <span className="measurement-readouts__label">Peak</span>{" "}
              <strong>{values.ready ? decimal(values.peak, 3) : "—"}</strong>
            </span>
          )}
        </div>
        <p className="measurement-plot__technical">
          {mode === "spectrum" ? (
            <>
              {values.ready
                ? `FFT ${values.fftSize.toLocaleString()} · Δf = ${decimal(values.resolution, 2)} Hz · smoothing ${values.smoothing.toFixed(2)}. `
                : ""}
              Blackman window: peaks spread across bins.
              {values.frequency
                ? ` Dashed: configured f₀ = ${values.frequency} Hz and harmonics.`
                : " Strongest bin ≠ estimated fundamental."}
            </>
          ) : (
            <>
              {values.ready
                ? `${values.triggered ? "Rising-zero trigger" : "Latest sample window"} · ${(values.sampleRate / 1000).toFixed(1)} kHz samples. `
                : ""}
              A stable capture, not real-time movement of individual cycles.
            </>
          )}
          {values.outsideScale && mode === "waveform"
            ? " Peaks exceed the visible ±1 range."
            : ""}
          {frozen && values.ready ? ` Held capture: ${sourceName}.` : ""}
        </p>
        <p id={descriptionId} className="visual-sr-only">
          {descriptor} {frozen ? "Frozen captured data." : "Live data."}
        </p>
      </figcaption>
    </figure>
  );
}

export default MeasurementPlot;
