import { useEffect, useRef, useState } from "react";
import { MAX_FILE_BYTES } from "../audio/dsp";
import {
  parseRecordingManifest,
  recordingAssetPath,
  recordingMimeType,
  type RecordingCatalog,
  type RecordingMetadata,
} from "../audio/recordings";
import "./recordings.css";

export type { RecordingMetadata } from "../audio/recordings";
export interface RecordingShelfProps {
  /** The owner stores metadata alongside the selected file to retain attribution. */
  onSelect: (file: File, metadata: RecordingMetadata) => void | Promise<void>;
}

const base = import.meta.env.BASE_URL;
let manifestRequest: Promise<RecordingCatalog> | null = null;

function loadCatalog(retry = false): Promise<RecordingCatalog> {
  if (manifestRequest && !retry) return manifestRequest;
  manifestRequest = (async () => {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 10000);
    try {
      const response = await fetch(`${base}recordings/manifest.json`, {
        signal: controller.signal,
        cache: "no-cache",
      });
      if (!response.ok)
        throw new Error(
          `Recording catalog could not load (HTTP ${response.status}).`,
        );
      const text = await response.text();
      if (text.length > 256000)
        throw new Error("Recording catalog is too large.");
      let data: unknown;
      try {
        data = JSON.parse(text);
      } catch {
        throw new Error("Recording catalog contains invalid JSON.");
      }
      return parseRecordingManifest(data);
    } catch (error) {
      return {
        recordings: [],
        errors: [
          controller.signal.aborted
            ? "Recording catalog timed out. The rest of the studio is still available."
            : error instanceof Error
              ? error.message
              : "Recording catalog could not load.",
        ],
      };
    } finally {
      clearTimeout(timeout);
    }
  })();
  return manifestRequest;
}

async function boundedBlob(
  response: Response,
  controller: AbortController,
): Promise<Blob> {
  const length = Number(response.headers.get("content-length") ?? 0);
  if (length > MAX_FILE_BYTES)
    throw new Error("This configured recording exceeds the 100 MB limit.");
  const type = response.headers.get("content-type")?.split(";")[0].trim() ?? "";
  if (type === "text/html")
    throw new Error(
      "The configured audio asset returned a web page. Check that its file is included.",
    );
  if (!response.body) {
    const blob = await response.blob();
    if (blob.size > MAX_FILE_BYTES)
      throw new Error("This configured recording exceeds the 100 MB limit.");
    return blob;
  }
  const reader = response.body.getReader();
  const parts: BlobPart[] = [];
  let total = 0;
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > MAX_FILE_BYTES) {
        await reader.cancel();
        controller.abort();
        throw new Error("This configured recording exceeds the 100 MB limit.");
      }
      parts.push(value.slice());
    }
  } finally {
    reader.releaseLock();
  }
  return new Blob(parts, { type });
}

/** Empty by default: no recordings or pretend recording buttons are shipped. */
export function RecordingShelf({ onSelect }: RecordingShelfProps) {
  const [catalog, setCatalog] = useState<RecordingCatalog | null>(null);
  const [pendingId, setPendingId] = useState<string | null>(null);
  const [error, setError] = useState("");
  const controllerRef = useRef<AbortController | null>(null);
  const generationRef = useRef(0);
  const mountedRef = useRef(true);

  useEffect(() => {
    mountedRef.current = true;
    void loadCatalog().then((result) => {
      if (mountedRef.current) setCatalog(result);
    });
    return () => {
      mountedRef.current = false;
      generationRef.current++;
      controllerRef.current?.abort();
    };
  }, []);

  async function select(recording: RecordingMetadata) {
    controllerRef.current?.abort();
    const controller = new AbortController();
    controllerRef.current = controller;
    const generation = ++generationRef.current;
    setPendingId(recording.id);
    setError("");
    let timedOut = false;
    const timeout = setTimeout(() => {
      timedOut = true;
      controller.abort();
    }, 20000);
    try {
      const response = await fetch(recordingAssetPath(recording.file, base), {
        signal: controller.signal,
      });
      if (!response.ok)
        throw new Error(
          `“${recording.title}” could not load (HTTP ${response.status}). Check its configured file.`,
        );
      const blob = await boundedBlob(response, controller);
      if (blob.size === 0)
        throw new Error("The configured recording is empty.");
      if (!mountedRef.current || generation !== generationRef.current) return;
      const file = new File([blob], recording.file, {
        type: blob.type.startsWith("audio/")
          ? blob.type
          : recordingMimeType(recording.file),
      });
      clearTimeout(timeout);
      await onSelect(file, recording);
    } catch (failure) {
      controller.abort();
      if (!mountedRef.current || generation !== generationRef.current) return;
      setError(
        timedOut
          ? "This recording took longer than 20 seconds to load. Try again."
          : failure instanceof Error
            ? failure.message
            : "The recording could not be opened.",
      );
    } finally {
      clearTimeout(timeout);
      if (mountedRef.current && generation === generationRef.current) {
        setPendingId(null);
        controllerRef.current = null;
      }
    }
  }

  if (!catalog || (!catalog.recordings.length && !catalog.errors.length))
    return null;
  return (
    <section className="recording-shelf" aria-label="Attributed recordings">
      {catalog.recordings.length > 0 && (
        <>
          <div className="recording-shelf__heading">
            <div>
              <span className="eyebrow">RECORDINGS TO EXPLORE</span>
              <h3>The recording collection.</h3>
            </div>
            <p>
              Load a recording, then press Play.
              <br />
              These audio files include source and licence credit.
            </p>
          </div>
          <ul className="recording-shelf__list">
            {catalog.recordings.map((recording) => (
              <li key={recording.id}>
                <div>
                  <strong>{recording.title}</strong>
                  <span>
                    {recording.instrument}
                    {recording.nominalFundamentalHz
                      ? ` · nominal ${recording.nominalFundamentalHz} Hz at original speed`
                      : ""}
                  </span>
                  <small>
                    {recording.credit} · {recording.license} ·{" "}
                    <a
                      href={recording.sourceUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      Recording source ↗
                    </a>
                  </small>
                </div>
                <button
                  type="button"
                  className="subtle-button"
                  disabled={pendingId === recording.id}
                  onClick={() => void select(recording)}
                >
                  {pendingId === recording.id ? "Loading…" : "Load recording"}
                </button>
              </li>
            ))}
          </ul>
        </>
      )}
      {pendingId && (
        <p className="recording-shelf__message" role="status">
          Loading the selected recording from this website…
        </p>
      )}
      {error && (
        <p className="recording-shelf__error" role="alert">
          {error}
        </p>
      )}
      {catalog.errors.length > 0 && (
        <details className="recording-shelf__issues">
          <summary>Recording catalog needs attention</summary>
          <ul>
            {catalog.errors.map((issue, index) => (
              <li key={index}>{issue}</li>
            ))}
          </ul>
          <button
            type="button"
            className="subtle-button"
            onClick={() => {
              setCatalog(null);
              void loadCatalog(true).then((result) => {
                if (mountedRef.current) setCatalog(result);
              });
            }}
          >
            Reload catalog
          </button>
        </details>
      )}
    </section>
  );
}

export default RecordingShelf;
