import { useEffect, useState } from "react";
import { engine, type SourceId } from "./audio/engine";
import { useSound } from "./useSound";
import { Icon } from "./components/Icon";
import { ScienceGuide } from "./components/ScienceGuide";
import { SoundCabinet } from "./components/SoundCabinet";
import { ToneLab } from "./labs/ToneLab";
import { TimbreLab } from "./labs/TimbreLab";
import { FileLab } from "./labs/FileLab";
import type { RecordingMetadata } from "./components/RecordingShelf";
type Lab = "shape" | "timbre" | "your-sound";
const validLabs: Lab[] = ["shape", "timbre", "your-sound"];
const fromHash = (): Lab =>
  validLabs.includes(location.hash.slice(1) as Lab)
    ? (location.hash.slice(1) as Lab)
    : "shape";
const sourceNames: Record<SourceId, string> = {
  tone: "Tone oscillator",
  a: "Harmonic sound A",
  b: "Harmonic sound B",
  file: "Your local recording",
  cabinet: "Sound cabinet",
};
export default function App() {
  const s = useSound();
  const [lab, setLab] = useState<Lab>(fromHash);
  const [guide, setGuide] = useState(false);
  const [presentation, setPresentation] = useState(false);
  const [entered, setEntered] = useState(!!location.hash);
  const [recording, setRecording] = useState<RecordingMetadata | null>(null);
  useEffect(() => {
    const onHash = () => {
      const next = fromHash();
      if (next !== lab) {
        engine.stop();
        setLab(next);
        setEntered(true);
      }
    };
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  }, [lab]);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setPresentation(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);
  useEffect(() => {
    document.documentElement.classList.toggle(
      "presentation-active",
      presentation,
    );
    return () =>
      document.documentElement.classList.remove("presentation-active");
  }, [presentation]);
  const navigate = (next: Lab) => {
    engine.stop();
    setLab(next);
    setEntered(true);
    location.hash = next;
  };
  const enter = () => {
    setEntered(true);
    location.hash = "shape";
    requestAnimationFrame(() =>
      document.getElementById("studio")?.scrollIntoView({
        behavior: matchMedia("(prefers-reduced-motion: reduce)").matches
          ? "instant"
          : "smooth",
        block: "start",
      }),
    );
  };
  const skipToStudio = () => {
    setEntered(true);
    requestAnimationFrame(() => {
      const studio = document.getElementById("studio");
      studio?.focus({ preventScroll: true });
      studio?.scrollIntoView({ behavior: "instant", block: "start" });
    });
  };
  const play = () => {
    if (s.playing) {
      engine.pause();
      return;
    }
    const source: SourceId =
      lab === "your-sound"
        ? "file"
        : lab === "timbre"
          ? s.activeSource === "b"
            ? "b"
            : "a"
          : "tone";
    void engine.play(source);
  };
  const sourceSilent =
    s.activeSource === "tone"
      ? s.amplitude === 0
      : s.activeSource === "a"
        ? s.normalizationA.silent
        : s.activeSource === "b"
          ? s.normalizationB.silent
          : false;
  const listening = s.playing && !s.muted && s.volume > 0 && !sourceSilent;
  const status = s.error
    ? "Needs attention"
    : s.visibilityPaused
      ? "Paused while away"
      : s.muted
        ? "Listening muted"
        : s.playing && (s.volume === 0 || sourceSilent)
          ? "Selected · silent"
          : s.playing
            ? "Listening"
            : s.activated
              ? "Listening paused"
              : "Ready to explore";
  return (
    <div className={`app-shell ${presentation ? "presentation" : ""}`}>
      <a
        className="skip-link"
        href="#studio"
        onClick={(e) => {
          e.preventDefault();
          skipToStudio();
        }}
      >
        Skip to the experiment
      </a>
      <header className="site-header">
        <a
          className="brand"
          href="#shape"
          onClick={() => navigate("shape")}
          aria-label="Sonic Lab home"
        >
          <span className="brand-mark">
            <svg
              viewBox="0 0 32 32"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.8"
              strokeLinecap="round"
              aria-hidden="true"
            >
              <path d="M5 14v4M10.5 9v14M16 4v24M21.5 9v14M27 14v4" />
            </svg>
          </span>
          <span>
            sonic<span className="brand-light">lab</span>
            <small>THE ANIMATED SCIENCE STUDIO</small>
          </span>
        </a>
        <div className="header-right">
          <span className="grade-badge">Grade 9 · Sound</span>
          <button
            className="guide-button"
            onClick={() => setGuide(true)}
            aria-label="Field guide"
          >
            <Icon name="book" size={18} />
            <span>Field guide</span>
          </button>
          <button
            className={`presentation-button ${presentation ? "active" : ""}`}
            onClick={() => setPresentation(!presentation)}
            aria-pressed={presentation}
            aria-label={presentation ? "Exit presentation" : "Present"}
          >
            <Icon name={presentation ? "close" : "expand"} size={18} />
            <span>{presentation ? "Exit presentation" : "Present"}</span>
          </button>
          <button
            className={`header-mute ${s.muted ? "muted" : ""}`}
            onClick={() => engine.setMuted(!s.muted)}
            aria-pressed={s.muted}
            aria-label={s.muted ? "Unmute listening" : "Mute listening"}
            title={s.muted ? "Unmute listening" : "Mute listening"}
          >
            <Icon name={s.muted ? "mute" : "volume"} size={20} />
            <span>{s.muted ? "Muted" : "Mute"}</span>
          </button>
        </div>
      </header>
      <main>
        {!entered && (
          <section className="intro">
            <div className="intro-copy">
              <span className="intro-kicker">
                <span /> A STUDIO FOR CURIOUS MINDS
              </span>
              <h1>
                See sound.
                <br />
                <span>Hear physics.</span>
              </h1>
              <p>
                Step into a studio where every sound
                <br className="desktop-break" /> becomes an experiment.
              </p>
              <div className="intro-actions">
                <button className="primary-button" onClick={enter}>
                  Enter the studio
                  <Icon name="arrow" size={18} />
                </button>
                <button
                  className="text-button"
                  onClick={() => navigate("timbre")}
                >
                  Discover timbre
                  <Icon name="chevron" size={15} />
                </button>
              </div>
            </div>
            <figure className="intro-art">
              <img
                src={`${import.meta.env.BASE_URL}assets/studio-hero.webp`}
                alt="A rounded teal tabletop speaker, golden tuning fork and wooden percussion block in a warmly lit studio."
                fetchPriority="high"
              />
              <figcaption>
                Original studio artwork · the measurements are below
              </figcaption>
              <span className="art-tag">
                <span /> MADE OF CURIOSITY
              </span>
            </figure>
          </section>
        )}
        <section
          id="studio"
          className="studio"
          aria-label="Interactive sound studio"
          tabIndex={-1}
        >
          <nav className="lab-navigation" aria-label="Laboratories">
            {[
              { id: "shape", num: "01", name: "Shape the sound", icon: "wave" },
              {
                id: "timbre",
                num: "02",
                name: "The timbre studio",
                icon: "music",
              },
              {
                id: "your-sound",
                num: "03",
                name: "Your sound studio",
                icon: "upload",
              },
            ].map((item) => (
              <button
                key={item.id}
                aria-current={lab === item.id ? "page" : undefined}
                className={lab === item.id ? "active" : ""}
                onClick={() => navigate(item.id as Lab)}
              >
                <span className="nav-number">{item.num}</span>
                <Icon
                  name={item.icon as "wave" | "music" | "upload"}
                  size={18}
                />
                <span>{item.name}</span>
                <span className="nav-indicator" />
              </button>
            ))}
          </nav>
          <div className="listening-bar">
            <div className="main-playback">
              <button
                className="primary-button play-main"
                onClick={play}
                disabled={
                  !s.playing &&
                  lab === "your-sound" &&
                  (!s.file || s.file.loading || !!s.file.error)
                }
                aria-label={s.playing ? "Pause listening" : "Play sound"}
              >
                <Icon name={s.playing ? "pause" : "play"} size={18} />
                <span>{s.playing ? "Pause" : "Play sound"}</span>
              </button>
              <button
                className="stop-button"
                onClick={() => engine.stop()}
                aria-label="Stop all sound"
              >
                <Icon name="stop" size={17} />
              </button>
              <div className="source-status">
                <strong>
                  <i className={`status-dot ${listening ? "active" : ""}`} />
                  {status}
                </strong>
                <span>
                  {sourceNames[s.activeSource]}
                  {s.activeSource === "cabinet" && s.cabinetName
                    ? ` · ${s.cabinetName}`
                    : ""}
                </span>
              </div>
            </div>
            <label className="listening-volume">
              <Icon name={s.muted ? "mute" : "volume"} size={18} />
              <span>Listening volume</span>
              <input
                type="range"
                min="0"
                max="100"
                step="1"
                value={Math.round(s.volume * 100)}
                onChange={(e) => engine.setVolume(Number(e.target.value) / 100)}
              />
              <output>{Math.round(s.volume * 100)}%</output>
            </label>
          </div>
          {!s.activated && (
            <p className="activation-note">
              Press <strong>Play sound</strong> to activate audio. Begin with
              your device volume low.
            </p>
          )}
          {s.error && (
            <div className="error-banner" role="alert">
              <span>{s.error}</span>
              <button
                className="icon-button"
                aria-label="Dismiss error"
                onClick={() => engine.clearError()}
              >
                <Icon name="close" size={16} />
              </button>
            </div>
          )}
          {s.visibilityPaused && (
            <p className="status-banner" role="status">
              Listening paused when you left the tab. Press Play to resume.
            </p>
          )}
          <div className="lab-content" key={lab}>
            {lab === "shape" ? (
              <ToneLab />
            ) : lab === "timbre" ? (
              <TimbreLab />
            ) : (
              <FileLab recording={recording} onRecordingChange={setRecording} />
            )}
          </div>
        </section>
        <SoundCabinet />
      </main>
      <footer className="site-footer">
        <div>
          <span className="footer-brand">soniclab</span>
          <span>See sound. Hear physics. Stay curious.</span>
        </div>
        <div>
          <button className="text-button" onClick={() => setGuide(true)}>
            Explore the science
            <Icon name="arrow" size={15} />
          </button>
          <span>Real audio. Thoughtful experiments.</span>
        </div>
      </footer>
      <ScienceGuide open={guide} onClose={() => setGuide(false)} />
    </div>
  );
}
