/** Metadata for an actual, locally hosted recording with explicit attribution. */
export interface RecordingMetadata {
  id: string;
  title: string;
  /** A basename under public/recordings/. Remote audio URLs are not accepted. */
  file: string;
  instrument: string;
  nominalFundamentalHz?: number;
  sourceUrl: string;
  license: string;
  credit: string;
}

export interface RecordingCatalog {
  recordings: RecordingMetadata[];
  errors: string[];
}

const filenamePattern =
  /^[a-zA-Z0-9][a-zA-Z0-9._-]*\.(mp3|wav|wave|ogg|oga|opus|m4a|aac|flac|webm|mp4|aiff|aif)$/i;
export function isRecordingFilename(value: unknown): value is string {
  return (
    typeof value === "string" &&
    value.length <= 180 &&
    !value.includes("..") &&
    filenamePattern.test(value)
  );
}

export function isRecordingSourceUrl(value: unknown): value is string {
  if (typeof value !== "string" || value.length > 2048) return false;
  try {
    const url = new URL(value);
    return (
      url.protocol === "https:" &&
      !url.username &&
      !url.password &&
      url.hostname.length > 0 &&
      !url.hostname.endsWith(".invalid")
    );
  } catch {
    return false;
  }
}

function nonempty(value: unknown, maximum: number): value is string {
  return (
    typeof value === "string" &&
    value.trim().length > 0 &&
    value.length <= maximum
  );
}

/** Reject malformed entries individually so a broken addition cannot break the lab.
 * This validates structure and local paths, not whether a claimed licence is true.
 */
export function parseRecordingManifest(value: unknown): RecordingCatalog {
  if (!Array.isArray(value))
    return {
      recordings: [],
      errors: ["Recording manifest must be a JSON array."],
    };
  if (value.length > 100)
    return {
      recordings: [],
      errors: ["Recording manifest must contain at most 100 entries."],
    };
  const recordings: RecordingMetadata[] = [];
  const errors: string[] = [];
  const ids = new Set<string>();
  for (let index = 0; index < value.length; index++) {
    const entry = value[index] as Record<string, unknown> | null;
    const prefix = `Recording ${index + 1}`;
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
      errors.push(`${prefix} must be an object.`);
      continue;
    }
    if (
      typeof entry.id !== "string" ||
      !/^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$/.test(entry.id)
    ) {
      errors.push(`${prefix} needs a simple unique id.`);
      continue;
    }
    if (ids.has(entry.id)) {
      errors.push(`${prefix} repeats id “${entry.id}”.`);
      continue;
    }
    if (!nonempty(entry.title, 120) || !nonempty(entry.instrument, 100)) {
      errors.push(`${prefix} needs a title and instrument.`);
      continue;
    }
    if (!isRecordingFilename(entry.file)) {
      errors.push(
        `${prefix} must name one audio file directly inside recordings/. Paths, URLs, and “..” are not allowed.`,
      );
      continue;
    }
    if (
      !isRecordingSourceUrl(entry.sourceUrl) ||
      !nonempty(entry.license, 200) ||
      !nonempty(entry.credit, 400)
    ) {
      errors.push(
        `${prefix} needs a valid HTTPS source, an explicit licence, and a credit.`,
      );
      continue;
    }
    if (
      entry.nominalFundamentalHz !== undefined &&
      (typeof entry.nominalFundamentalHz !== "number" ||
        !Number.isFinite(entry.nominalFundamentalHz) ||
        entry.nominalFundamentalHz <= 0 ||
        entry.nominalFundamentalHz > 20000)
    ) {
      errors.push(
        `${prefix} has an invalid nominal fundamental. Omit it for unpitched or complex recordings.`,
      );
      continue;
    }
    ids.add(entry.id);
    recordings.push({
      id: entry.id,
      title: entry.title.trim(),
      instrument: entry.instrument.trim(),
      file: entry.file,
      sourceUrl: entry.sourceUrl,
      license: entry.license.trim(),
      credit: entry.credit.trim(),
      ...(entry.nominalFundamentalHz === undefined
        ? {}
        : { nominalFundamentalHz: entry.nominalFundamentalHz as number }),
    });
  }
  return { recordings, errors };
}

/** Vite BASE_URL may be /, ./, or a repository subpath. */
export function recordingAssetPath(file: string, base: string): string {
  if (!isRecordingFilename(file))
    throw new Error("Invalid local recording filename.");
  return `${base.endsWith("/") ? base : `${base}/`}recordings/${file}`;
}

export function recordingMimeType(file: string): string {
  const extension = file.split(".").pop()?.toLowerCase();
  const types: Record<string, string> = {
    mp3: "audio/mpeg",
    wav: "audio/wav",
    wave: "audio/wav",
    ogg: "audio/ogg",
    oga: "audio/ogg",
    opus: "audio/ogg",
    m4a: "audio/mp4",
    mp4: "audio/mp4",
    aac: "audio/aac",
    flac: "audio/flac",
    webm: "audio/webm",
    aiff: "audio/aiff",
    aif: "audio/aiff",
  };
  return types[extension ?? ""] ?? "application/octet-stream";
}
