import { useEffect, useRef, useState } from "react";
import type { ReactNode } from "react";
import "./education.css";

interface ScienceGuideProps {
  open: boolean;
  onClose: () => void;
}
const SOURCES = {
  waves:
    "https://openstax.org/books/physics/pages/14-1-speed-of-sound-frequency-and-wavelength",
  propagation: "https://openstax.org/books/college-physics-2e/pages/17-1-sound",
  speed:
    "https://openstax.org/books/college-physics-2e/pages/17-2-speed-of-sound-frequency-and-wavelength",
  intensity:
    "https://openstax.org/books/physics/pages/14-2-sound-intensity-and-sound-level",
  levels:
    "https://openstax.org/books/college-physics-2e/pages/17-3-sound-intensity-and-sound-level",
  hearing: "https://openstax.org/books/college-physics-2e/pages/17-6-hearing",
  ultrasound:
    "https://openstax.org/books/college-physics-2e/pages/17-7-ultrasound",
  harmonics:
    "https://openstax.org/books/physics/pages/14-4-sound-interference-and-resonance",
  fft: "https://developer.mozilla.org/en-US/docs/Web/API/AnalyserNode/fftSize",
};
function Source({ name, href }: { name: string; href: string }) {
  return (
    <a className="guide-source" href={href} target="_blank" rel="noreferrer">
      {name} <span aria-hidden="true">↗</span>
    </a>
  );
}
function Topic({
  title,
  children,
  initiallyOpen = false,
}: {
  title: string;
  children: ReactNode;
  initiallyOpen?: boolean;
}) {
  return (
    <details className="guide-topic" open={initiallyOpen || undefined}>
      <summary>
        {title}
        <span aria-hidden="true">+</span>
      </summary>
      <div className="guide-topic-body">{children}</div>
    </details>
  );
}

export function ScienceGuide({ open, onClose }: ScienceGuideProps) {
  const dialog = useRef<HTMLDialogElement>(null);
  const previousFocus = useRef<HTMLElement | null>(null);
  const [topic, setTopic] = useState<"essentials" | "world" | "measurements">(
    "essentials",
  );
  useEffect(() => {
    const element = dialog.current;
    if (!element) return;
    if (open && !element.open) {
      previousFocus.current = document.activeElement as HTMLElement | null;
      element.showModal();
    } else if (!open && element.open) {
      element.close();
      previousFocus.current?.focus();
    }
  }, [open]);

  return (
    <dialog
      ref={dialog}
      className="science-guide"
      aria-labelledby="science-guide-title"
      onCancel={(event) => {
        event.preventDefault();
        onClose();
      }}
      onClick={(event) => {
        if (event.target !== event.currentTarget) return;
        const bounds = event.currentTarget.getBoundingClientRect();
        if (
          event.clientX < bounds.left ||
          event.clientX > bounds.right ||
          event.clientY < bounds.top ||
          event.clientY > bounds.bottom
        )
          onClose();
      }}
    >
      <div className="science-guide-inner">
        <header className="guide-heading">
          <div>
            <span className="edu-eyebrow">The science notebook</span>
            <h2 id="science-guide-title">
              A little clarity. A lot of discovery.
            </h2>
            <p>
              Grade 9 sound essentials, with deeper details when you want them.
            </p>
          </div>
          <button
            type="button"
            className="guide-close"
            onClick={onClose}
            aria-label="Close scientific guide"
            autoFocus
          >
            ×
          </button>
        </header>
        <nav className="guide-navigation" aria-label="Scientific guide topics">
          <button
            type="button"
            aria-pressed={topic === "essentials"}
            onClick={() => setTopic("essentials")}
          >
            Sound essentials
          </button>
          <button
            type="button"
            aria-pressed={topic === "world"}
            onClick={() => setTopic("world")}
          >
            Sound in the world
          </button>
          <button
            type="button"
            aria-pressed={topic === "measurements"}
            onClick={() => setTopic("measurements")}
          >
            Behind the measurements
          </button>
        </nav>
        <div className="guide-content" key={topic}>
          {topic === "essentials" && (
            <>
              <Topic
                title="Amplitude is a size. Loudness is a perception."
                initiallyOpen
              >
                <p>
                  Amplitude describes the maximum departure from an equilibrium
                  value. For sound, this can mean particle displacement or
                  pressure variation. In this studio, the amplitude knob changes
                  a <strong>digital signal gain</strong>.
                </p>
                <p>
                  For the same waveform and frequency, increasing gain usually
                  makes the sound seem louder. What reaches your ears also
                  depends on the device, system volume, distance and room. The
                  percentage is not calibrated dB SPL.
                </p>
                <div className="guide-formula">
                  Double comparable amplitude → +6.02 dB of signal level
                </div>
                <p>
                  For an ideal travelling wave in a fixed medium, intensity is
                  proportional to pressure amplitude squared. Doubling pressure
                  amplitude gives four times the intensity; subjective loudness
                  need not double.
                </p>
                <Source
                  name="OpenStax · Intensity and level"
                  href={SOURCES.intensity}
                />
              </Topic>
              <Topic title="Frequency counts vibrations. Pitch describes the note.">
                <p>
                  Frequency is the number of complete oscillations each second,
                  measured in hertz (Hz). A 440 Hz oscillator makes 440 cycles
                  per second. The period is the time for one cycle.
                </p>
                <div className="guide-formula">
                  T = 1/f <span>440 Hz → T ≈ 2.27 ms</span>
                </div>
                <p>
                  A higher frequency generally gives a higher pitch. For
                  periodic musical tones, doubling frequency raises pitch by one
                  octave: 220 → 440 → 880 Hz. At a fixed plot time window,
                  doubling frequency shows twice as many cycles.
                </p>
                <Source
                  name="OpenStax · Frequency and wavelength"
                  href={SOURCES.waves}
                />
              </Topic>
              <Topic title="Timbre explains why the same note can sound different.">
                <p>
                  A pure sine tone contains one frequency. A harmonic mixture
                  contains a fundamental and integer multiples of it: f, 2f, 3f…
                  Changing their relative strengths changes the waveform and
                  sound character.
                </p>
                <p>
                  Real instruments also differ in attack, decay, noise,
                  inharmonic partials and how their spectra change over time.
                  The flute-like and piano-like presets here are sustained
                  harmonic synthesis, not recordings or full instrument models.
                </p>
                <Source name="OpenStax · Harmonics" href={SOURCES.harmonics} />
              </Topic>
              <Topic title="Sound in air moves as a longitudinal wave.">
                <p>
                  A vibrating source produces moving compressions and
                  rarefactions. Air particles oscillate approximately parallel
                  to the propagation direction, near their equilibrium
                  positions. They do not ride a transverse sine curve or travel
                  all the way to your ear with the wave.
                </p>
                <p>
                  In the air model, watch the highlighted particle move to and
                  fro while the compression pattern travels. The motion is
                  slowed and displacement exaggerated; it is not a measured view
                  of air.
                </p>
                <Source
                  name="OpenStax · Sound propagation"
                  href={SOURCES.propagation}
                />
              </Topic>
            </>
          )}
          {topic === "world" && (
            <>
              <Topic
                title="Speed, frequency and wavelength belong together."
                initiallyOpen
              >
                <div className="guide-formula">
                  v = fλ <span>speed = frequency × wavelength</span>
                </div>
                <p>
                  At a fixed sound speed, a higher frequency has a shorter
                  wavelength. Using 343 m/s as an illustrative air speed, a 440
                  Hz tone has wavelength about 0.78 m.
                </p>
                <p>
                  Sound needs matter to propagate: it travels through gases,
                  liquids and solids, but not a vacuum. Speed depends on the
                  medium and its conditions, including temperature. It does not
                  simply increase because the note is higher.
                </p>
                <Source name="OpenStax · Speed of sound" href={SOURCES.speed} />
              </Topic>
              <Topic title="An echo is a return journey.">
                <p>
                  When sound reflects from a surface, it can return to the
                  listener. A distinct delayed repetition is an echo. Many
                  overlapping reflections create reverberation; soft, absorbing
                  materials help reduce it.
                </p>
                <div className="guide-formula">
                  2d = vt <span>d = vt/2 for the outward-and-return path</span>
                </div>
                <p>
                  Example: a reflected pulse returns after 0.20 s. If sound
                  speed is 340 m/s and the source and receiver are together, the
                  reflector is 34 m away.
                </p>
                <Source
                  name="OpenStax · Reflections and time of flight"
                  href={SOURCES.ultrasound}
                />
              </Topic>
              <Topic title="Hearing has a range, and people differ.">
                <p>
                  About 20 Hz–20,000 Hz is the usual reference range for young
                  human hearing. Individual limits vary, and the upper limit
                  often falls with age. Your speakers or headphones have limits
                  too.
                </p>
                <p>
                  The outer ear collects sound; the eardrum and middle-ear bones
                  transmit vibration; the inner ear converts it into nerve
                  signals. Loudness depends on frequency as well as intensity.
                </p>
                <p>
                  This studio is not a hearing test or a sound-level meter.
                  Begin quietly, choose a comfortable volume and stop if a sound
                  feels uncomfortable. A digital volume setting cannot guarantee
                  a particular listening level.
                </p>
                <Source name="OpenStax · Hearing" href={SOURCES.hearing} />
              </Topic>
              <Topic title="Ultrasound and SONAR use sound as a probe.">
                <p>
                  Frequencies above 20 kHz are called ultrasound; below 20 Hz,
                  infrasound. Reflected sound can reveal boundaries and
                  distances. Ultrasound is used for imaging, cleaning and
                  detecting flaws.
                </p>
                <p>
                  SONAR measures travel time through water. For a stationary
                  reflector and a known, approximately constant sound speed,
                  distance equals speed × round-trip time ÷ 2. The water speed
                  must be used, not the air speed. SONAR systems can use
                  different frequency ranges.
                </p>
                <Source
                  name="OpenStax · Ultrasound and SONAR"
                  href={SOURCES.ultrasound}
                />
              </Topic>
            </>
          )}
          {topic === "measurements" && (
            <>
              <Topic title="What these numbers actually measure" initiallyOpen>
                <dl className="guide-definitions">
                  <div>
                    <dt>Digital amplitude</dt>
                    <dd>
                      A sample value or gain in the computer. It has no unit of
                      pascals.
                    </dd>
                  </div>
                  <div>
                    <dt>Pressure amplitude</dt>
                    <dd>
                      The size of a physical pressure variation in a medium,
                      measured in pascals.
                    </dd>
                  </div>
                  <div>
                    <dt>Intensity</dt>
                    <dd>Sound power per area, measured in W/m².</dd>
                  </div>
                  <div>
                    <dt>Signal level</dt>
                    <dd>
                      A logarithmic ratio to a stated reference. Digital levels
                      here are not acoustic dB SPL.
                    </dd>
                  </div>
                  <div>
                    <dt>Loudness</dt>
                    <dd>
                      A listener's perception, influenced by intensity,
                      frequency and context.
                    </dd>
                  </div>
                </dl>
                <p>
                  The analysers sit before the listening gate, mute and master
                  volume. Synthesized measurements can therefore remain visible
                  while listening is stopped or muted. File measurements follow
                  the playing media; pausing a file stops its signal.
                </p>
                <Source
                  name="OpenStax · Level and intensity"
                  href={SOURCES.levels}
                />
              </Topic>
              <Topic title="RMS, normalization and fair comparisons">
                <div className="guide-formula">
                  RMS = √(mean of squared samples)
                  <span>ΔL = 20 log₁₀(A₂/A₁), for comparable amplitudes</span>
                </div>
                <p>
                  RMS summarizes signal level over a sample window. A sine with
                  peak A has RMS A/√2. The timbre lab targets a common RMS and
                  scales a mixture down if its peak bound needs protection. The
                  displayed normalization information reports this.
                </p>
                <p>
                  Equal RMS, equal peak, equal fundamental amplitude and equal
                  subjective loudness are different comparisons. The tone lab
                  keeps a fixed source-headroom factor, so turning its amplitude
                  knob does not secretly normalize the trace back to the same
                  height.
                </p>
              </Topic>
              <Topic title="How to read the waveform and the FFT">
                <p>
                  The waveform uses real audio samples. Horizontal positions
                  correspond to sample index ÷ sample rate, in milliseconds. The
                  vertical scale stays fixed. Freeze holds a captured
                  measurement rather than drawing a new ideal curve.
                </p>
                <div className="guide-formula">
                  FFT bin spacing = sample rate / FFT size
                </div>
                <p>
                  A spectrum divides a finite sample window into frequency bins.
                  Windowing reduces leakage but broadens peaks; smoothing
                  averages changes across frames. A peak near 440 Hz need not
                  land exactly on 440 Hz.
                </p>
                <p>
                  For synthesized sounds, the configured fundamental is known.
                  The strongest measured spectral bin is separately labelled. In
                  an arbitrary recording, the strongest bin is not necessarily
                  the fundamental; Sonic Lab does not pretend to estimate a
                  single pitch for every recording.
                </p>
                <Source name="MDN · FFT sample windows" href={SOURCES.fft} />
              </Topic>
              <Topic title="What the air model simplifies">
                <div className="guide-formula">
                  ξ(x,t) = A cos(kx − ωt)<span>Compression ∝ −∂ξ/∂x</span>
                </div>
                <p>
                  The model uses a sinusoidal longitudinal displacement,
                  including when the selected audible waveform is more complex.
                  Compression depends on neighbouring particles getting closer,
                  not simply on a particle's displacement.
                </p>
                <p>
                  Model time runs at 1/220 of real acoustic time: 440 Hz appears
                  as 2 oscillations per second. Particle displacement is bounded
                  and visually exaggerated. Digital gain influences the
                  illustration but is not calibrated to displacement in metres
                  or pressure in pascals.
                </p>
              </Topic>
            </>
          )}
        </div>
        <footer className="guide-footer">
          Original teaching explanations · Reference links open in a new tab.{" "}
          <button type="button" className="edu-text-button" onClick={onClose}>
            Back to the studio →
          </button>
        </footer>
      </div>
    </dialog>
  );
}
